pastorCommentaryData["누가복음_8_7"] = {
본문: "더러는 가시떨기 속에 떨어지매 가시가 함께 자라서 기운을 막았고",
표1_원어분석: [{"원어":"ἀκανθῶν (아칸돈)", "의미_문법":"가시떨기 - 명사 복수 속격. 가시나무들", "설교포인트":"세상의 염려와 유혹이 말씀의 성장을 막는다"},{"원어":"συμφυεῖσαι (쉼퓌에이사이)", "의미_문법":"함께 자라다 - 분사 부정과거. 동시에 성장함", "설교포인트":"말씀과 세상의 관심이 동시에 자라면 결국 세상이 이긴다"},{"원어":"ἀπέπνιξαν (아페프닉산)", "의미_문법":"기운을 막다/질식시키다 - 동사 부정과거. 숨을 막아 죽임", "설교포인트":"세상의 것들이 서서히 영적 생명을 질식시킨다"},{"원어":"μέσῳ (메소)", "의미_문법":"가운데/속에 - 명사. 한가운데", "설교포인트":"세상 한가운데서 세상에 물들지 않는 것이 도전이다"}],
표2_역사적배경: [{"항목":"가시떨기의 특성", "내용":"팔레스타인의 가시떨기는 뿌리가 깊고 성장이 빠르다. 겉보기에 제거된 것 같아도 뿌리가 남아있으면 다시 자란다", "목회적활용":"세상의 유혹은 완전히 뿌리 뽑지 않으면 다시 올라온다"},{"항목":"기운을 막는 과정", "내용":"가시떨기는 좋은 식물보다 빨리 자라 햇빛, 수분, 양분을 모두 빼앗아간다. 서서히 질식시키는 과정", "목회적활용":"세상의 관심사가 서서히 영적 생명을 질식시킨다는 것을 경계해야 한다"},{"항목":"함께 자람의 문제", "내용":"말씀과 세상의 관심이 동시에 마음에 있으면 결국 더 강한 쪽이 승리한다. 가시떨기가 더 강하다", "목회적활용":"두 마음을 품는 것은 결국 세상 쪽으로 기울게 된다"}],
표3_신학적의미: [{"교리":"세상의 유혹", "설명":"예수님의 해석에 따르면 가시떨기는 이생의 염려, 재리, 일락이다. 이것들이 말씀을 질식시킨다", "관련구절":"딤전 6:9-10"},{"교리":"이중적 삶의 불가능", "설명":"하나님과 세상을 동시에 섬길 수 없다. 둘 중 하나를 선택해야 한다", "관련구절":"마 6:24"},{"교리":"온전한 결실", "설명":"가시떨기 땅은 씨가 죽지 않고 자라기는 하지만 온전한 결실을 맺지 못한다", "관련구절":"마 13:22"}],
표4_예표론: [{"구분":"구약 예표", "내용":"에덴동산의 저주로 가시와 엉겅퀴가 남(창 3:18)", "그리스도연결":"가시떨기는 타락의 결과이며 그리스도가 가시 면류관을 쓰심으로 저주를 대신 지셨다"},{"구분":"성취", "내용":"예수님이 가시떨기 비유로 세상의 유혹을 경고하심", "그리스도연결":"세상의 유혹에서 승리하시고 제자들에게도 승리의 길을 보여주심"},{"구분":"완성", "내용":"새 하늘과 새 땅에서 가시떨기(저주)가 영원히 사라짐(계 22:3)", "그리스도연결":"저주가 완전히 제거된 영원한 나라의 완성"}],
표5_매튜헨리: [{"영어원문":"The thorns did not destroy the seed, but choked it so that it brought no fruit to perfection", "한국어번역":"가시떨기는 씨를 죽이지 않았지만 질식시켜 완전한 열매를 맺지 못하게 했다", "핵심통찰":"세상의 염려가 신앙을 죽이지 않더라도 열매를 막을 수 있다"},{"영어원문":"The cares of this world, the deceitfulness of riches, and the pleasures of life choke the word", "한국어번역":"이 세상의 염려, 재물의 유혹, 삶의 쾌락이 말씀을 질식시킨다", "핵심통찰":"세 가지 가시떨기: 염려, 물질, 쾌락"}],
표6_설교자료: [{"대지":"제목", "내용":"가시떨기의 질식 — 세상이 막는 신앙의 결실", "예화_적용":"세상의 염려와 유혹이 서서히 영적 생명을 질식시킨다"},{"대지":"서론", "내용":"가시떨기 땅의 씨앗은 길가처럼 싹도 못 틔우거나 바위처럼 금방 마르지 않는다. 자라기는 자라지만 가시떨기에 기운이 막혀 열매를 맺지 못한다. 이것이 가장 위험한 유형이다", "예화_적용":"교회는 다니지만 열매 없는 신앙이 가장 안타까운 상태이다"},{"대지":"1대지: 함께 자람 (이중적 삶)", "내용":"말씀과 세상의 관심이 동시에 자라는 이중적 삶의 위험", "예화_적용":"주일에는 하나님, 평일에는 세상을 추구하는 이중 생활"},{"대지":"2대지: 기운을 막음 (서서히 질식)", "내용":"가시떨기는 한순간에 죽이지 않고 서서히 질식시킨다", "예화_적용":"바쁘다는 핑계로 기도 시간이 줄고 말씀 묵상이 사라지는 과정"},{"대지":"3대지: 열매를 맺지 못함 (무결실의 비극)", "내용":"자라기는 하지만 온전한 열매를 맺지 못하는 안타까운 상태", "예화_적용":"오래 교회 다니지만 삶의 변화가 없는 것이 가시떨기의 결과이다"},{"대지":"결론", "내용":"가시떨기를 제거하는 유일한 방법은 뿌리부터 뽑는 것이다. 이생의 염려를 하나님께 맡기고, 물질의 유혹을 물리치고, 세상의 쾌락 대신 하나님의 기쁨을 선택하라", "예화_적용":"매일의 결단으로 가시떨기를 제거하고 말씀이 온전히 자라게 하라"}],
표7_찬송가: [{"새찬송가":"391", "통일찬송가":"356", "제목":"믿음으로 서리라", "선정이유":"세상의 유혹에 흔들리지 않는 믿음"},{"새찬송가":"407", "통일찬송가":"396", "제목":"이 세상에 근심된 일이", "선정이유":"세상 염려를 주님께 맡김"},{"새찬송가":"382", "통일찬송가":"288", "제목":"내 평생에 가는 길", "선정이유":"세상 속에서도 주님의 길을 걸음"},{"새찬송가":"542", "통일찬송가":"369", "제목":"주 안에 있는 나에게", "선정이유":"세상의 유혹을 이기는 평안"}],
표8_상담적용: [{"상황":"세상의 걱정으로 기도가 안 되는 분", "성경원리":"이생의 염려가 가시떨기처럼 말씀의 성장을 막는다", "실제적용":"걱정 목록을 적고 하나하나 하나님께 맡기는 기도를 하라. 걱정이 곧 기도 제목이다"},{"상황":"물질에 대한 욕심이 강해 신앙생활에 방해가 되는 분", "성경원리":"재리(물질의 유혹)가 말씀을 질식시키는 가시떨기이다", "실제적용":"청지기의 관점으로 물질을 바라보라. 소유가 아니라 관리자로서의 삶을 선택하라"},{"상황":"세상적 쾌락에 빠져 신앙이 형식적인 분", "성경원리":"일락(쾌락)이 영적 생명을 서서히 질식시킨다", "실제적용":"참된 기쁨의 원천은 하나님이시다. 세상의 쾌락 대신 하나님 안에서의 기쁨을 경험하라"}],
표9_교차참조: [{"구절":"창 3:17-18", "연결점":"땅이 네게 가시와 엉겅퀴를 낼 것이라", "구분":"구약"},{"구절":"잠 24:30-31", "연결점":"게으른 자의 밭을 지나며 보니 가시덤불이 그 지면에 가득하고", "구분":"구약"},{"구절":"렘 4:3", "연결점":"너희 묵은 땅을 기경하고 가시덤불 속에 파종하지 말라", "구분":"구약"},{"구절":"사 5:6", "연결점":"내가 황폐하게 하여 가지를 치거나 김을 매지 못하게 하리니 찔레와 가시가 날 것이며", "구분":"구약"},{"구절":"딤전 6:9-10", "연결점":"부하려 하는 자들은 시험과 올무에 빠지고", "구분":"신약"},{"구절":"마 6:24", "연결점":"너희가 하나님과 재물을 겸하여 섬기지 못하느니라", "구분":"신약"},{"구절":"요일 2:15-17", "연결점":"이 세상이나 세상에 있는 것들을 사랑하지 말라", "구분":"신약"},{"구절":"막 4:18-19", "연결점":"가시떨기에 뿌려진 자 - 마가복음 병행본문", "구분":"신약"}]
};

pastorCommentaryData["누가복음_8_8"] = {
본문: "더러는 좋은 땅에 떨어지매 나서 백 배의 결실을 하였느니라 이 말씀을 하시고 외쳐 가라사대 들을 귀 있는 자는 들을지어다 하시니",
표1_원어분석: [{"원어":"ἀγαθήν (아가덴)", "의미_문법":"좋은/선한 - 형용사. 질적으로 우수한", "설교포인트":"좋은 땅이란 말씀을 받아들일 준비가 된 마음이다"},{"원어":"ἑκατονταπλασίονα (헤카톤타플라시오나)", "의미_문법":"백 배 - 형용사. 놀라운 수확량", "설교포인트":"말씀을 잘 받아들이면 상상을 초월하는 열매를 맺는다"},{"원어":"ἐφώνει (에포네이)", "의미_문법":"외치다 - 동사 미완료 과거. 큰 소리로 반복해서 외침", "설교포인트":"이 말씀의 중요성을 강조하기 위해 예수님이 직접 외치셨다"},{"원어":"ἀκούειν (아쿠에인)", "의미_문법":"듣다 - 동사 부정사. 주의 깊게 듣다", "설교포인트":"듣는 것이 모든 결실의 시작이다"}],
표2_역사적배경: [{"항목":"백 배의 수확", "내용":"팔레스타인에서 일반적인 수확량은 7-10배였다. 백 배의 수확은 초자연적인 풍성함을 의미한다", "목회적활용":"하나님의 말씀이 좋은 땅에 뿌려지면 상상을 초월하는 결실을 맺는다"},{"항목":"외쳐 가라사대", "내용":"예수님이 특별히 큰 소리로 외치신 것은 이 비유의 결론이 매우 중요하기 때문이다. 주의를 집중시키는 강조법", "목회적활용":"'들을 귀 있는 자'라는 표현은 모든 사람이 듣지만 깨닫는 것은 별개라는 의미"},{"항목":"들을 귀", "내용":"물리적 청각이 아닌 영적 이해와 순종의 귀를 의미한다. 자발적으로 마음을 열고 듣는 태도", "목회적활용":"말씀을 영적으로 분별하여 듣고 순종하는 것이 '들을 귀'이다"}],
표3_신학적의미: [{"교리":"풍성한 결실", "설명":"좋은 땅에 떨어진 씨앗이 백 배의 결실을 맺는 것은 하나님 나라의 풍성함을 보여준다", "관련구절":"요 15:5"},{"교리":"듣는 행위의 중요성", "설명":"예수님이 특별히 외치시며 '들을 귀'를 강조한 것은 듣는 것이 신앙의 핵심임을 보여준다", "관련구절":"롬 10:17"},{"교리":"선택적 계시", "설명":"비유는 모든 사람에게 열려있지만 깨달음은 마음의 상태에 따라 선택적으로 주어진다", "관련구절":"마 11:25"}],
표4_예표론: [{"구분":"구약 예표", "내용":"이삭이 그 땅에서 백 배의 결실을 거둠(창 26:12)", "그리스도연결":"하나님의 축복이 임하면 백 배의 풍성한 결실이 가능하다"},{"구분":"성취", "내용":"좋은 땅에 뿌려진 말씀이 백 배의 결실을 맺음", "그리스도연결":"그리스도의 말씀을 잘 받아들이는 자에게 풍성한 열매가 주어진다"},{"구분":"완성", "내용":"하나님 나라의 최종 수확(계 14:15)", "그리스도연결":"마지막 때에 모든 결실이 거두어지는 최종 추수"}],
표5_매튜헨리: [{"영어원문":"The good ground brought forth fruit a hundredfold – this shows the amazing productiveness of the word when it is rightly received", "한국어번역":"좋은 땅은 백 배의 열매를 맺었다 - 이것은 말씀이 올바르게 받아들여질 때의 놀라운 생산성을 보여준다", "핵심통찰":"말씀을 올바르게 받아들이면 놀라운 결실을 맺는다"},{"영어원문":"He that hath ears to hear, let him hear – this is a call to serious attention and spiritual understanding", "한국어번역":"들을 귀 있는 자는 들을지어다 - 이것은 진지한 주의와 영적 이해를 요구하는 부르심이다", "핵심통찰":"영적 듣기는 자연적 능력이 아니라 은혜의 선물이다"}],
표6_설교자료: [{"대지":"제목", "내용":"좋은 땅 백 배의 결실 — 말씀이 열매 맺는 삶", "예화_적용":"말씀을 잘 받아들이면 상상을 초월하는 열매를 맺는다"},{"대지":"서론", "내용":"네 가지 땅 중 좋은 땅만이 백 배의 결실을 맺었다. 예수님은 이 비유의 결론으로 특별히 큰 소리로 외치셨다. 들을 귀 있는 자는 들으라", "예화_적용":"4분의 1의 확률이 아니라 내가 어떤 땅이 될 것인가의 선택이다"},{"대지":"1대지: 좋은 땅 (준비된 마음)", "내용":"길가처럼 단단하지 않고, 바위처럼 얕지 않고, 가시떨기가 없는 깊고 부드러운 땅", "예화_적용":"겸손하고 열린 마음으로 말씀을 받아들이는 자세"},{"대지":"2대지: 백 배의 결실 (풍성한 열매)", "내용":"일반 수확량의 10배 이상인 초자연적 풍성함. 하나님의 축복이 더해진 결과", "예화_적용":"인간의 노력을 넘어 하나님의 은혜가 더해질 때 놀라운 결실이 가능하다"},{"대지":"3대지: 들을 귀 (영적 청취)", "내용":"예수님이 특별히 외치시며 강조하신 '듣는 것'의 중요성", "예화_적용":"매주 설교를 듣지만 삶이 변하지 않는 것은 '들을 귀'가 없기 때문이다"},{"대지":"결론", "내용":"좋은 땅이 되는 비결은 세 가지이다. 단단한 마음을 깨뜨리는 회개, 깊이 뿌리내리는 훈련, 가시떨기를 제거하는 결단. 이 세 가지가 갖추어질 때 백 배의 결실을 경험할 수 있다", "예화_적용":"오늘 나의 마음을 좋은 땅으로 만들겠다는 결단이 필요하다"}],
표7_찬송가: [{"새찬송가":"230", "통일찬송가":"241", "제목":"성경의 귀한 말씀", "선정이유":"말씀의 놀라운 결실의 능력"},{"새찬송가":"235", "통일찬송가":"195", "제목":"말씀으로 이 세상을", "선정이유":"말씀의 능력과 결실"},{"새찬송가":"365", "통일찬송가":"398", "제목":"가서 복음을 전하여라", "선정이유":"씨를 뿌리는 자의 사명"},{"새찬송가":"208", "통일찬송가":"198", "제목":"기뻐하며 경배하세", "선정이유":"풍성한 결실에 대한 감사"}],
표8_상담적용: [{"상황":"신앙생활이 열매 없이 무기력한 분", "성경원리":"좋은 땅은 백 배의 결실을 맺었다. 마음의 상태가 결과를 결정한다", "실제적용":"마음의 상태를 점검하라. 단단한 부분, 얕은 부분, 가시떨기를 제거하고 좋은 땅을 만들라"},{"상황":"성경을 읽어도 깨달음이 없는 분", "성경원리":"'들을 귀 있는 자는 들으라' - 영적 듣기가 필요하다", "실제적용":"성경을 읽기 전에 성령님께 조명을 구하는 기도를 하라. 열린 마음이 깨달음의 조건이다"},{"상황":"작은 결실에 실망하는 분", "성경원리":"좋은 땅은 백 배의 결실을 맺었다. 하나님의 약속은 풍성하다", "실제적용":"인내하라. 씨앗이 자라는 데는 시간이 필요하다. 때가 되면 반드시 결실을 맺는다"}],
표9_교차참조: [{"구절":"창 26:12", "연결점":"이삭이 그 땅에서 백 배의 결실을 거두었으니", "구분":"구약"},{"구절":"시 1:3", "연결점":"시냇가에 심은 나무가 철을 따라 열매를 맺으며", "구분":"구약"},{"구절":"사 55:10-11", "연결점":"내 말이 내게로 헛되이 돌아오지 아니하고 반드시 열매를 맺으리라", "구분":"구약"},{"구절":"호 10:12", "연결점":"너희가 자기를 위하여 의를 심고 인애를 거두라", "구분":"구약"},{"구절":"요 15:5", "연결점":"내 안에 거하면 사람이 열매를 많이 맺나니", "구분":"신약"},{"구절":"롬 10:17", "연결점":"믿음은 들음에서 나며 들음은 그리스도의 말씀으로 말미암았느니라", "구분":"신약"},{"구절":"갈 6:9", "연결점":"우리가 선을 행하되 낙심하지 말지니 피곤하지 아니하면 때가 이르매 거두리라", "구분":"신약"},{"구절":"골 1:6", "연결점":"이 복음이 온 천하에 열매를 맺어 자라는도다", "구분":"신약"}]
};

pastorCommentaryData["누가복음_8_9"] = {
본문: "제자들이 이 비유의 뜻을 물으니",
표1_원어분석: [{"원어":"ἐπηρώτων (에페로톤)", "의미_문법":"묻다 - 동사 미완료 과거. 반복적으로 물음", "설교포인트":"모르면 물어야 한다. 질문은 배움의 시작이다"},{"원어":"μαθηταί (마데타이)", "의미_문법":"제자들 - 명사 복수. 배우는 자들", "설교포인트":"제자는 모르는 것을 솔직히 인정하고 질문하는 자이다"},{"원어":"παραβολή (파라볼레)", "의미_문법":"비유 - 명사. 옆에 놓은 것, 비교", "설교포인트":"영적 진리를 깨닫기 위해서는 설명이 필요하다"},{"원어":"τίς (티스)", "의미_문법":"무엇 - 의문대명사. 의미가 무엇인지", "설교포인트":"비유의 표면이 아니라 깊은 의미를 알고자 함"}],
표2_역사적배경: [{"항목":"제자들의 질문", "내용":"유대 교육 전통에서 학생이 스승에게 질문하는 것은 당연한 학습 과정이었다. 제자들은 비유의 표면적 이야기는 이해했지만 영적 의미를 몰랐다", "목회적활용":"모르는 것을 솔직히 질문하는 것이 성장의 시작이다"},{"항목":"개인적 질문", "내용":"공개적으로가 아니라 따로 질문한 것은 제자들에게만 비밀이 허락됨을 보여준다(10절)", "목회적활용":"영적 비밀은 진지하게 구하는 자에게 열린다"},{"항목":"비유 해석의 필요", "내용":"비유는 자명하지 않다. 해석이 필요하며 예수님만이 참된 해석을 주실 수 있다", "목회적활용":"성경을 읽을 때 성령의 조명이 필요하다"}],
표3_신학적의미: [{"교리":"계시의 필요성", "설명":"영적 진리는 자연적 지혜로 알 수 없고 하나님의 계시가 필요하다", "관련구절":"고전 2:14"},{"교리":"구하는 자에게 주시는 은혜", "설명":"제자들이 물었기에 해석을 받았다. 구하는 자에게 주시는 하나님의 원리", "관련구절":"마 7:7-8"},{"교리":"점진적 성장", "설명":"제자들도 처음에는 비유를 이해하지 못했다. 영적 성장은 점진적이다", "관련구절":"막 4:34"}],
표4_예표론: [{"구분":"구약 예표", "내용":"모세가 하나님의 뜻을 알기 위해 여호와께 물음(민 27:5)", "그리스도연결":"하나님의 뜻을 알기 위해 직접 물어야 한다"},{"구분":"성취", "내용":"제자들이 예수님께 비유의 의미를 물음", "그리스도연결":"그리스도는 진리의 최종 해석자이시다"},{"구분":"완성", "내용":"성령이 모든 진리 가운데로 인도하심(요 16:13)", "그리스도연결":"성령이 영원히 함께하시며 모든 진리를 깨닫게 하실 것이다"}],
표5_매튜헨리: [{"영어원문":"The disciples asked him the meaning of the parable; it is good to enquire into the meaning of God's word", "한국어번역":"제자들이 비유의 의미를 물었다. 하나님의 말씀의 의미를 탐구하는 것은 좋은 일이다", "핵심통찰":"말씀의 의미를 구하는 것은 경건한 행위이다"},{"영어원문":"What we do not understand we should ask about; God is willing to explain his word to those who sincerely desire to know it", "한국어번역":"이해하지 못하는 것은 물어야 한다. 하나님은 진심으로 알기를 원하는 자에게 기꺼이 말씀을 설명하신다", "핵심통찰":"진심으로 구하면 하나님은 기꺼이 가르쳐 주신다"}],
표6_설교자료: [{"대지":"제목", "내용":"물을 수 있는 은혜 — 제자의 질문", "예화_적용":"모르면 물어야 한다. 질문은 성장의 시작이다"},{"대지":"서론", "내용":"제자들은 비유를 듣고 그 의미를 몰랐다. 그러나 모르는 것을 부끄러워하지 않고 예수님께 직접 물었다. 이 솔직한 질문이 하나님 나라의 비밀을 여는 열쇠가 되었다", "예화_적용":"모르면서 아는 척하는 것보다 솔직히 질문하는 것이 지혜이다"},{"대지":"1대지: 모르는 것의 인정 (겸손)", "내용":"제자들은 예수님의 비유를 이해하지 못했음을 솔직히 인정했다", "예화_적용":"영적 성장의 첫걸음은 내가 모른다는 것을 인정하는 것이다"},{"대지":"2대지: 직접 묻는 용기 (적극성)", "내용":"군중은 그냥 지나갔지만 제자들은 따로 나아가 물었다", "예화_적용":"하나님 앞에 적극적으로 나아가 구하는 자가 얻는다"},{"대지":"3대지: 해석을 받는 은혜 (계시)", "내용":"물었기에 예수님이 직접 해석해 주셨다. 구하지 않았다면 얻지 못했을 것이다", "예화_적용":"기도로 구하면 성령님이 말씀을 조명해 주신다"},{"대지":"결론", "내용":"제자의 특권은 예수님께 직접 물을 수 있다는 것이었다. 오늘 우리도 기도를 통해 하나님께 직접 물을 수 있다. 말씀을 읽고 모를 때, 삶의 방향이 불확실할 때, 주님께 물으라", "예화_적용":"기도는 하나님께 질문하고 답을 듣는 시간이다"}],
표7_찬송가: [{"새찬송가":"235", "통일찬송가":"195", "제목":"말씀으로 이 세상을", "선정이유":"말씀의 깊은 의미를 구함"},{"새찬송가":"543", "통일찬송가":"370", "제목":"내 주여 뜻대로", "선정이유":"하나님의 뜻을 묻는 기도"},{"새찬송가":"407", "통일찬송가":"396", "제목":"이 세상에 근심된 일이", "선정이유":"주님께 물으며 의탁하는 삶"},{"새찬송가":"230", "통일찬송가":"241", "제목":"성경의 귀한 말씀", "선정이유":"성경의 깊은 뜻을 탐구"}],
표8_상담적용: [{"상황":"성경이 어렵고 이해가 안 되는 분", "성경원리":"제자들도 비유를 이해하지 못해 직접 물었다. 모르는 것은 부끄러운 것이 아니다", "실제적용":"소그룹이나 성경공부를 통해 질문하라. 혼자 고민하지 말고 함께 배우라"},{"상황":"기도 중에 하나님의 응답이 없다고 느끼는 분", "성경원리":"제자들이 물었을 때 예수님은 바로 가르쳐 주셨다", "실제적용":"구체적으로 물으라. 막연한 기도보다 구체적인 질문이 구체적인 응답을 이끈다"},{"상황":"신앙의 깊이가 부족하다고 느끼는 분", "성경원리":"제자들은 표면을 넘어 깊은 의미를 구했다", "실제적용":"말씀을 읽을 때 '이것이 나에게 무엇을 말하는가'라고 물으라. 적용을 구하는 것이 깊이이다"}],
표9_교차참조: [{"구절":"민 27:5", "연결점":"모세가 그들의 사건을 여호와 앞에 고하니라", "구분":"구약"},{"구절":"잠 2:3-5", "연결점":"명철을 불러 구하며 은을 구하는 것 같이 그것을 찾으면", "구분":"구약"},{"구절":"단 2:18", "연결점":"다니엘이 하나님께 비밀을 알게 해달라고 기도함", "구분":"구약"},{"구절":"시 119:18", "연결점":"내 눈을 열어서 주의 율법에서 놀라운 것을 보게 하소서", "구분":"구약"},{"구절":"마 7:7-8", "연결점":"구하라 그리하면 너희에게 주실 것이요", "구분":"신약"},{"구절":"약 1:5", "연결점":"너희 중에 누구든지 지혜가 부족하거든 하나님께 구하라", "구분":"신약"},{"구절":"요 16:13", "연결점":"진리의 성령이 오시면 그가 너희를 모든 진리 가운데로 인도하시리니", "구분":"신약"},{"구절":"고전 2:10-12", "연결점":"성령은 모든 것 곧 하나님의 깊은 것까지도 통달하시느니라", "구분":"신약"}]
};

pastorCommentaryData["누가복음_8_10"] = {
본문: "가라사대 하나님 나라의 비밀을 아는 것이 너희에게는 허락되었으나 다른 사람에게는 비유로 하나니 이는 저희로 보아도 보지 못하며 들어도 깨닫지 못하게 하려 함이니라",
표1_원어분석: [{"원어":"μυστήρια (뮈스테리아)", "의미_문법":"비밀들 - 명사 복수. 이전에 감추어져 있다가 계시된 것", "설교포인트":"하나님 나라의 비밀은 은혜로 열리는 것이다"},{"원어":"δέδοται (데도타이)", "의미_문법":"주어지다 - 동사 완료 수동. 하나님에 의해 허락됨", "설교포인트":"영적 깨달음은 인간의 능력이 아니라 하나님의 선물이다"},{"원어":"βλέποντες (블레폰테스)", "의미_문법":"보면서 - 분사 현재. 물리적으로 보지만", "설교포인트":"눈으로 보면서도 영적 진리를 보지 못할 수 있다"},{"원어":"συνιῶσιν (쉬니오신)", "의미_문법":"깨닫다 - 동사 가정법 현재. 이해하다/통찰하다", "설교포인트":"듣는 것과 깨닫는 것은 다른 차원이다"}],
표2_역사적배경: [{"항목":"비밀(뮈스테리온)의 의미", "내용":"헬라어 뮈스테리온은 이전에 감추어져 있다가 특정 시점에 계시되는 진리를 의미한다. 비밀종교의 용어가 아닌 계시의 용어", "목회적활용":"하나님 나라의 진리는 인간이 발견하는 것이 아니라 하나님이 열어주시는 것이다"},{"항목":"이사야 인용", "내용":"사 6:9-10의 인용으로 이스라엘의 영적 둔감함에 대한 심판적 선언. 보고도 보지 못하고 들어도 깨닫지 못하는 것은 자발적 거부의 결과", "목회적활용":"말씀을 계속 거부하면 영적 둔감함이 심판으로 굳어진다"},{"항목":"제자들의 특권", "내용":"제자들에게 비밀이 허락된 것은 그들의 능력이 아니라 하나님의 은혜였다", "목회적활용":"말씀을 깨닫는 것 자체가 은혜이다. 교만할 이유가 없다"}],
표3_신학적의미: [{"교리":"선택적 계시", "설명":"하나님은 진리를 구하는 자에게 드러내시고 거부하는 자에게는 감추신다", "관련구절":"마 11:25-26"},{"교리":"사법적 둔감함", "설명":"반복적인 거부는 결국 하나님의 심판적 둔감함으로 이어진다", "관련구절":"롬 1:24-28"},{"교리":"은혜로서의 깨달음", "설명":"영적 진리를 이해하는 것은 인간의 지적 능력이 아니라 하나님의 은혜의 선물", "관련구절":"마 16:17"}],
표4_예표론: [{"구분":"구약 예표", "내용":"이사야에게 주어진 심판 메시지(사 6:9-10)", "그리스도연결":"이스라엘의 영적 둔감함이 예수님 시대에도 반복됨"},{"구분":"성취", "내용":"예수님이 비유로 가르치시며 제자들에게만 비밀을 여심", "그리스도연결":"메시아를 통한 하나님 나라의 비밀 계시"},{"구분":"완성", "내용":"비밀이 완전히 드러나는 날(고전 13:12)", "그리스도연결":"비유가 필요 없는 완전한 앎의 시대"}],
표5_매튜헨리: [{"영어원문":"To you it is given to know the mysteries of the kingdom of God – this is a privilege that comes from grace, not merit", "한국어번역":"하나님 나라의 비밀을 아는 것이 너희에게는 허락되었다 - 이것은 공로가 아닌 은혜에서 오는 특권이다", "핵심통찰":"영적 깨달음은 은혜의 선물이다"},{"영어원문":"Those who willfully shut their eyes against the light shall be justly left in darkness", "한국어번역":"고의로 빛에 눈을 감는 자는 정당하게 어둠에 남겨질 것이다", "핵심통찰":"빛을 거부하면 어둠이 심판이 된다"}],
표6_설교자료: [{"대지":"제목", "내용":"비밀이 열리는 사람, 닫히는 사람", "예화_적용":"같은 말씀 앞에서 깨닫는 자와 못 깨닫는 자가 나뉜다"},{"대지":"서론", "내용":"예수님은 하나님 나라의 비밀이 제자들에게는 허락되었지만 다른 사람에게는 비유로 남아있다고 하셨다. 이것은 불공평이 아니라 마음의 태도에 따른 결과이다", "예화_적용":"같은 태양 아래서 밀랍은 녹고 진흙은 굳듯이 같은 말씀이 마음에 따라 다르게 작용한다"},{"대지":"1대지: 비밀의 허락 (은혜의 선물)", "내용":"제자들에게 비밀이 허락된 것은 그들의 능력이 아니라 하나님의 은혜", "예화_적용":"깨달음을 얻었다면 교만할 것이 아니라 감사해야 한다"},{"대지":"2대지: 보아도 보지 못함 (영적 둔감)", "내용":"물리적으로 보고 듣지만 영적 진리를 깨닫지 못하는 비극적 상태", "예화_적용":"매주 설교를 듣지만 삶이 변하지 않는 것이 이 상태이다"},{"대지":"3대지: 비유의 이중 기능 (드러냄과 감춤)", "내용":"비유는 구하는 자에게는 진리를 드러내고 거부하는 자에게는 감추는 이중 기능", "예화_적용":"성경을 열심히 읽어도 구하지 않으면 비밀은 열리지 않는다"},{"대지":"결론", "내용":"하나님 나라의 비밀은 열쇠가 필요하다. 그 열쇠는 겸손한 마음과 진실한 구함이다. 오늘 말씀 앞에 겸손히 서서 비밀을 열어달라고 기도하자", "예화_적용":"성경을 읽기 전에 '주님, 제 눈을 열어주소서'라고 기도하라"}],
표7_찬송가: [{"새찬송가":"235", "통일찬송가":"195", "제목":"말씀으로 이 세상을", "선정이유":"하나님의 말씀 계시"},{"새찬송가":"200", "통일찬송가":"199", "제목":"전능의 하나님", "선정이유":"하나님의 비밀을 여시는 능력"},{"새찬송가":"288", "통일찬송가":"256", "제목":"어둔 밤 마음에 잠겨", "선정이유":"영적 눈이 열리는 은혜"},{"새찬송가":"543", "통일찬송가":"370", "제목":"내 주여 뜻대로", "선정이유":"하나님의 뜻을 구하는 기도"}],
표8_상담적용: [{"상황":"성경을 읽어도 깨달음이 없는 분", "성경원리":"하나님 나라의 비밀은 '허락'된 것이다. 인간의 노력만으로 되지 않는다", "실제적용":"말씀을 읽기 전에 성령님의 조명을 구하라. 겸손한 마음이 깨달음의 조건이다"},{"상황":"하나님이 불공평하다고 느끼는 분", "성경원리":"비밀이 감추어진 것은 하나님의 불공평이 아니라 거부하는 마음의 결과이다", "실제적용":"마음을 열고 구하면 하나님은 기꺼이 비밀을 열어주신다"},{"상황":"오랜 신앙생활에도 영적 성장이 더딘 분", "성경원리":"보아도 보지 못하고 들어도 깨닫지 못하는 것은 마음의 둔감함 때문이다", "실제적용":"의숙함이 무감각함이 되지 않도록 매일 새로운 마음으로 말씀 앞에 서라"}],
표9_교차참조: [{"구절":"사 6:9-10", "연결점":"이 백성의 마음을 둔하게 하며 귀가 막히고 눈이 감기게 하라", "구분":"구약"},{"구절":"단 2:28", "연결점":"오직 은밀한 것을 나타내시는 하늘에 계신 하나님이 계시니", "구분":"구약"},{"구절":"시 25:14", "연결점":"여호와의 비밀이 그를 경외하는 자에게 있음이여", "구분":"구약"},{"구절":"암 3:7", "연결점":"주 여호와께서는 자기의 비밀을 그 종 선지자들에게 보이지 아니하시고는 결코 행하심이 없으시리라", "구분":"구약"},{"구절":"마 11:25-26", "연결점":"지혜롭고 슬기 있는 자에게는 숨기시고 어린 아이들에게는 나타내심을 감사하나이다", "구분":"신약"},{"구절":"고전 2:14", "연결점":"육에 속한 사람은 하나님의 성령의 일을 받지 아니하나니", "구분":"신약"},{"구절":"엡 1:9", "연결점":"그 뜻의 비밀을 우리에게 알리신 것이요", "구분":"신약"},{"구절":"롬 11:25", "연결점":"이 비밀을 너희가 모르기를 내가 원하지 아니하노니", "구분":"신약"}]
};

pastorCommentaryData["누가복음_8_11"] = {
본문: "이 비유는 이러하니라 씨는 하나님의 말씀이요",
표1_원어분석: [{"원어":"σπόρος (스포로스)", "의미_문법":"씨/종자 - 명사. 뿌려지는 것", "설교포인트":"하나님의 말씀은 생명을 품은 씨앗이다"},{"원어":"λόγος (로고스)", "의미_문법":"말씀 - 명사. 하나님의 말씀/진리", "설교포인트":"복음의 핵심은 하나님의 말씀이다"},{"원어":"τοῦ θεοῦ (투 데우)", "의미_문법":"하나님의 - 명사 속격. 하나님에게서 온", "설교포인트":"이 말씀의 출처는 하나님이시다"},{"원어":"ἐστίν (에스틴)", "의미_문법":"~이다 - 동사 현재. 본질적 동일성", "설교포인트":"씨앗과 말씀은 동일한 것으로 선언됨"}],
표2_역사적배경: [{"항목":"비유 해석의 시작", "내용":"예수님이 직접 비유를 해석하시는 드문 경우이다. 씨 뿌리는 자의 비유가 그만큼 중요하기 때문", "목회적활용":"이 비유의 해석은 예수님이 직접 하셨으므로 가장 권위 있는 해석이다"},{"항목":"씨앗으로서의 말씀", "내용":"씨앗은 작지만 생명을 품고 있다. 하나님의 말씀도 겉으로는 단순한 글자이지만 영적 생명을 품고 있다", "목회적활용":"말씀 한 구절에도 생명을 변화시키는 능력이 담겨있다"},{"항목":"농업 비유의 배경", "내용":"당시 청중의 대부분이 농민이었으므로 씨앗과 땅의 비유는 가장 이해하기 쉬운 이미지였다", "목회적활용":"진리를 전할 때 상대방이 이해할 수 있는 언어를 사용하라"}],
표3_신학적의미: [{"교리":"하나님 말씀의 생명력", "설명":"씨앗에 생명이 있듯 하나님의 말씀에도 영적 생명이 있다. 말씀은 살아있고 운동력이 있다", "관련구절":"히 4:12"},{"교리":"말씀의 충분성", "설명":"씨앗 자체는 완전하다. 문제는 씨앗이 아니라 땅이다. 말씀은 완전하며 문제는 듣는 자의 마음이다", "관련구절":"딤후 3:16-17"},{"교리":"말씀 중심의 사역", "설명":"예수님의 사역의 핵심은 하나님의 말씀을 뿌리는 것이다", "관련구절":"요 1:1"}],
표4_예표론: [{"구분":"구약 예표", "내용":"이사야의 말씀 비유 - 비와 눈이 땅을 적시듯 하나님의 말씀이 열매를 맺음(사 55:10-11)", "그리스도연결":"하나님의 말씀은 반드시 목적한 바를 이루신다"},{"구분":"성취", "내용":"예수님이 '씨는 하나님의 말씀'이라고 직접 선언하심", "그리스도연결":"말씀이 육신이 되신 그리스도가 말씀의 본질을 밝히심"},{"구분":"완성", "내용":"말씀으로 새 하늘과 새 땅을 창조하심(벧후 3:13)", "그리스도연결":"말씀의 능력이 새 창조를 이루는 최종 완성"}],
표5_매튜헨리: [{"영어원문":"The seed is the word of God – this is the great truth upon which all the rest depends", "한국어번역":"씨는 하나님의 말씀이다 - 이것이 다른 모든 것이 의존하는 위대한 진리이다", "핵심통찰":"모든 영적 결실의 시작은 하나님의 말씀이다"},{"영어원문":"The word of God is seed for the soul; it is able to produce a harvest, but it must be sown in the heart", "한국어번역":"하나님의 말씀은 영혼을 위한 씨앗이다. 수확을 낼 수 있지만 마음에 뿌려져야 한다", "핵심통찰":"말씀이 마음에 뿌려져야 열매를 맺는다"}],
표6_설교자료: [{"대지":"제목", "내용":"씨는 하나님의 말씀이라 — 비유의 열쇠", "예화_적용":"모든 영적 결실의 시작은 하나님의 말씀이다"},{"대지":"서론", "내용":"예수님이 직접 비유를 해석하기 시작하신다. 첫 번째 해석의 열쇠는 '씨는 하나님의 말씀'이라는 선언이다. 이 한 문장이 비유 전체를 여는 열쇠이다", "예화_적용":"성경 해석의 가장 확실한 방법은 예수님의 해석을 따르는 것이다"},{"대지":"1대지: 씨앗의 특성 (생명력)", "내용":"씨앗은 작지만 생명을 품고 있어 좋은 땅에 떨어지면 큰 나무가 된다", "예화_적용":"말씀 한 구절이 한 사람의 인생을 완전히 바꿀 수 있다"},{"대지":"2대지: 하나님의 말씀 (완전한 씨앗)", "내용":"씨앗 자체는 완전하다. 어떤 씨앗이든 같은 생명력을 가지고 있다", "예화_적용":"성경의 어떤 부분이든 생명의 말씀이다. 좋아하는 구절만 읽지 말라"},{"대지":"3대지: 뿌려져야 할 씨앗 (선포의 사명)", "내용":"씨앗은 보관하는 것이 아니라 뿌려야 한다. 말씀도 전해져야 한다", "예화_적용":"말씀을 나 혼자 가지고 있지 말고 이웃에게 전하라"},{"대지":"결론", "내용":"씨는 하나님의 말씀이다. 이 단순한 진리가 모든 것을 결정한다. 말씀을 읽고, 묵상하고, 전하는 것이 그리스도인의 핵심 사명이다", "예화_적용":"매일 말씀을 읽는 것이 매일 씨를 뿌리는 것이다"}],
표7_찬송가: [{"새찬송가":"230", "통일찬송가":"241", "제목":"성경의 귀한 말씀", "선정이유":"하나님의 말씀의 귀한 가치"},{"새찬송가":"235", "통일찬송가":"195", "제목":"말씀으로 이 세상을", "선정이유":"말씀의 생명력"},{"새찬송가":"200", "통일찬송가":"199", "제목":"전능의 하나님", "선정이유":"하나님의 말씀의 권위"},{"새찬송가":"365", "통일찬송가":"398", "제목":"가서 복음을 전하여라", "선정이유":"말씀(씨앗)을 뿌리는 사명"}],
표8_상담적용: [{"상황":"성경 읽기가 지루하고 의미 없게 느껴지는 분", "성경원리":"씨앗은 작고 보잘것없어 보이지만 생명을 품고 있다. 말씀도 마찬가지이다", "실제적용":"재미없어 보여도 꾸준히 읽으라. 때가 되면 생명력이 폭발적으로 드러날 것이다"},{"상황":"말씀대로 살기 어려운 분", "성경원리":"씨앗이 자라려면 시간이 필요하다. 말씀도 마음에서 자라는 시간이 필요하다", "실제적용":"즉각적 변화를 기대하지 말고 인내하라. 매일 말씀을 묵상하면 서서히 변화가 일어난다"},{"상황":"전도의 결실이 보이지 않는 분", "성경원리":"씨앗은 뿌린 후 시간이 지나야 발아한다. 말씀도 마찬가지이다", "실제적용":"결실을 보지 못해도 계속 뿌리라. 하나님이 자라게 하신다"}],
표9_교차참조: [{"구절":"사 55:10-11", "연결점":"내 입에서 나가는 말도 그러하여 반드시 열매를 맺으리라", "구분":"구약"},{"구절":"시 119:105", "연결점":"주의 말씀은 내 발에 등이요 내 길에 빛이니이다", "구분":"구약"},{"구절":"렘 23:29", "연결점":"내 말이 불 같지 아니하냐 반석을 부수는 방망이 같지 아니하냐", "구분":"구약"},{"구절":"신 8:3", "연결점":"사람이 떡으로만 사는 것이 아니요 여호와의 입에서 나오는 모든 말씀으로 사는 줄", "구분":"구약"},{"구절":"히 4:12", "연결점":"하나님의 말씀은 살아 있고 활력이 있어", "구분":"신약"},{"구절":"벧전 1:23-25", "연결점":"살아 있고 항상 있는 하나님의 말씀으로 거듭난 것이니", "구분":"신약"},{"구절":"딤후 3:16-17", "연결점":"모든 성경은 하나님의 감동으로 된 것으로", "구분":"신약"},{"구절":"요 1:1", "연결점":"태초에 말씀이 계시니라 이 말씀이 하나님과 함께 계셨으니", "구분":"신약"}]
};

pastorCommentaryData["누가복음_8_12"] = {
본문: "길가에 있는 것은 말씀을 들은 자니 이에 마귀가 와서 그들로 믿어 구원을 얻지 못하게 하려고 말씀을 그 마음에서 빼앗는 것이요",
표1_원어분석: [{"원어":"παρὰ τὴν ὁδόν (파라 텐 호돈)", "의미_문법":"길가에 - 전치사구. 길 옆/가장자리", "설교포인트":"단단하게 굳어진 마음은 말씀이 뿌리내리지 못한다"},{"원어":"διάβολος (디아볼로스)", "의미_문법":"마귀/중상하는 자 - 명사. 대적자", "설교포인트":"마귀는 말씀이 마음에 뿌리내리는 것을 적극 방해한다"},{"원어":"αἴρει (아이레이)", "의미_문법":"빼앗다/들어올리다 - 동사 현재. 반복적 행위", "설교포인트":"마귀의 말씀 빼앗기는 지금도 계속되는 현재진행형이다"},{"원어":"πιστεύσαντες (피스튜산테스)", "의미_문법":"믿어 - 분사 과거. 믿는 행위", "설교포인트":"구원은 믿음을 통해서 온다"},{"원어":"σωθῶσιν (소도신)", "의미_문법":"구원을 얻다 - 동사 가정법 수동태", "설교포인트":"마귀의 궁극적 목적은 구원을 방해하는 것이다"}],
표2_역사적배경: [{"항목":"길가의 상태", "내용":"팔레스타인의 밭 사이 길은 사람들이 많이 다녀 땅이 단단하게 다져져 있었다. 씨앗이 땅속으로 들어갈 수 없었다", "목회적활용":"무관심과 무감각으로 굳어진 마음은 말씀을 받아들이지 못한다"},{"항목":"마귀의 활동", "내용":"유대 전통에서 사탄은 하나님의 일을 방해하는 대적자로 이해되었다. 예수님은 이를 실체적 존재로 가르치셨다", "목회적활용":"영적 전쟁의 실체를 인식하고 말씀을 지키는 데 경각심을 가져야 한다"},{"항목":"새가 먹어버림의 해석", "내용":"앞의 비유에서 새가 먹어버렸다는 것은 마귀가 말씀을 빼앗는 것으로 해석됨", "목회적활용":"예배 후 말씀을 곧 잊어버리는 것은 영적 공격의 결과일 수 있다"}],
표3_신학적의미: [{"교리":"마귀의 실체와 활동", "설명":"예수님은 마귀를 비유가 아닌 실체적 존재로 말씀하신다. 마귀는 말씀이 마음에 자리잡는 것을 적극적으로 방해한다", "관련구절":"벧전 5:8"},{"교리":"믿음과 구원의 관계", "설명":"구원은 믿음을 통해 온다. 마귀가 말씀을 빼앗는 이유는 믿음이 생기지 못하게 하여 구원을 방해하려는 것이다", "관련구절":"엡 2:8-9"},{"교리":"마음 밭의 상태", "설명":"말씀의 열매는 말씀 자체가 아니라 듣는 자의 마음 상태에 달려있다", "관련구절":"잠 4:23"}],
표4_예표론: [{"구분":"구약 예표", "내용":"에덴동산에서 뱀이 하나님의 말씀을 왜곡하고 빼앗은 것(창 3:1-5)이 첫 번째 선례", "그리스도연결":"마귀는 처음부터 하나님의 말씀을 빼앗는 자였다"},{"구분":"성취", "내용":"예수님이 광야 시험에서 마귀의 말씀 왜곡을 물리치심(눅 4:1-13)", "그리스도연결":"그리스도는 말씀으로 마귀를 이기신 승리자이시다"},{"구분":"완성", "내용":"마지막 때에 마귀가 영원히 결박됨(계 20:10)", "그리스도연결":"말씀을 빼앗는 자의 활동이 영원히 종식된다"}],
표5_매튜헨리: [{"영어원문":"The devil is a sworn enemy to our profiting by the word of God; and none do more to hinder our salvation than those that would hinder our faith", "한국어번역":"마귀는 우리가 하나님의 말씀으로 유익을 얻는 것의 맹세한 원수이다. 우리의 믿음을 방해하는 자보다 더 구원을 방해하는 자는 없다", "핵심통찰":"마귀의 핵심 전략은 믿음을 방해하는 것이다"},{"영어원문":"The wicked one cometh and catcheth away that which was sown; he is very vigilant and speedy to prevent the good effects of the word", "한국어번역":"악한 자가 와서 뿌려진 것을 빼앗는다. 그는 말씀의 좋은 효과를 막기 위해 매우 경계하고 신속하다", "핵심통찰":"마귀는 말씀의 효과를 막기 위해 신속하게 활동한다"}],
표6_설교자료: [{"대지":"제목", "내용":"길가 마음 — 마귀가 말씀을 빼앗는 현장", "예화_적용":"굳어진 마음은 말씀을 받지 못한다"},{"대지":"서론", "내용":"네 가지 땅 중 첫 번째 땅은 길가이다. 수많은 발에 밟혀 단단해진 길가는 씨앗이 뚫고 들어갈 수 없다. 예수님은 이것이 마귀가 말씀을 빼앗는 것이라고 해석하신다", "예화_적용":"예배 중에는 감동받았는데 교회 문을 나서면 다 잊어버리는 경험이 있는가"},{"대지":"1대지: 길가의 상태 (굳어진 마음)", "내용":"길가는 많은 사람이 밟아서 단단해진 땅이다. 세상의 소리에 익숙해져 말씀에 무감각해진 마음이다", "예화_적용":"스마트폰과 미디어에 중독되면 말씀이 들려도 마음에 새겨지지 않는다"},{"대지":"2대지: 마귀의 전략 (말씀 빼앗기)", "내용":"마귀는 말씀이 마음에 뿌리내리기 전에 빼앗는다. 이것이 마귀의 가장 효과적인 전략이다", "예화_적용":"설교 직후 세상 이야기로 말씀을 잊게 하는 것이 마귀의 전략이다"},{"대지":"3대지: 구원을 막는 방해 (믿음 방해)", "내용":"마귀의 궁극적 목적은 믿어 구원을 얻지 못하게 하는 것이다", "예화_적용":"전도할 때 상대방이 갑자기 마음을 닫는 것은 영적 전쟁의 현장이다"},{"대지":"결론", "내용":"우리의 마음이 길가처럼 굳어지지 않도록 항상 말씀 앞에 부드러운 마음을 유지하라. 예배 후에도 말씀을 묵상하고 지키라", "예화_적용":"예배 후 10분 묵상이 마귀의 빼앗기를 막는 방어벽이 된다"}],
표7_찬송가: [{"새찬송가":"391", "통일찬송가":"455", "제목":"지금까지 지내온 것", "선정이유":"영적 전쟁에서의 하나님의 보호"},{"새찬송가":"457", "통일찬송가":"350", "제목":"마귀들과 싸울지라", "선정이유":"마귀와의 영적 전쟁"},{"새찬송가":"389", "통일찬송가":"448", "제목":"주 안에 있는 나에게", "선정이유":"주 안에서의 영적 무장"},{"새찬송가":"230", "통일찬송가":"241", "제목":"성경의 귀한 말씀", "선정이유":"말씀을 마음에 지키는 것의 중요성"}],
표8_상담적용: [{"상황":"설교를 들어도 금방 잊어버리는 분", "성경원리":"마귀가 말씀을 빼앗는다고 예수님이 직접 경고하셨다", "실제적용":"예배 후 바로 핸드폰을 보지 말고 10분간 말씀을 묵상하라. 설교 노트를 작성하라"},{"상황":"전도하는데 상대방이 마음을 닫는 경우", "성경원리":"이것은 마귀가 활동하는 영적 전쟁의 현장이다", "실제적용":"기도로 영적 전쟁에 참여하라. 포기하지 말고 꾸준히 기도하며 사랑으로 다가가라"},{"상황":"신앙에 무관심한 가족을 둔 분", "성경원리":"굳어진 마음도 하나님이 깨뜨리실 수 있다", "실제적용":"말보다 기도와 삶으로 먼저 감동을 주라. 하나님이 그 마음을 부드럽게 하실 것이다"}],
표9_교차참조: [{"구절":"창 3:1-5", "연결점":"뱀이 하나님의 말씀을 왜곡하여 빼앗은 최초의 사건", "구분":"구약"},{"구절":"욥 1:6-12", "연결점":"사탄이 하나님 앞에서 욥을 참소하는 장면", "구분":"구약"},{"구절":"슥 3:1", "연결점":"사탄이 대제사장 여호수아를 대적하여 서 있음", "구분":"구약"},{"구절":"잠 4:23", "연결점":"네 마음을 지키라 생명의 근원이 이에서 남이니라", "구분":"구약"},{"구절":"벧전 5:8", "연결점":"너희 대적 마귀가 우는 사자같이 두루 다니며", "구분":"신약"},{"구절":"엡 6:11-12", "연결점":"마귀의 궤계를 능히 대적하기 위하여 하나님의 전신갑주를 입으라", "구분":"신약"},{"구절":"고후 4:3-4", "연결점":"이 세상 신이 믿지 아니하는 자들의 마음을 혼미케 하여", "구분":"신약"},{"구절":"약 4:7", "연결점":"마귀를 대적하라 그리하면 너희를 피하리라", "구분":"신약"}]
};

pastorCommentaryData["누가복음_8_13"] = {
본문: "바위 위에 있는 것은 말씀을 들을 때에 기쁨으로 받으나 뿌리가 없어 잠깐 믿다가 시험을 받을 때에 배반하는 자요",
표1_원어분석: [{"원어":"πέτραν (페트란)", "의미_문법":"바위 - 명사. 단단한 암반", "설교포인트":"바위 같은 마음은 겉은 받아들이는 듯하나 깊이가 없다"},{"원어":"χαρᾶς (카라스)", "의미_문법":"기쁨 - 명사 속격. 기쁨으로", "설교포인트":"감정적 반응만으로는 진정한 믿음이 아니다"},{"원어":"ῥίζαν (리잔)", "의미_문법":"뿌리 - 명사. 근본/기초", "설교포인트":"뿌리 없는 믿음은 시험 앞에서 무너진다"},{"원어":"πρὸς καιρόν (프로스 카이론)", "의미_문법":"잠깐 동안 - 전치사구. 일시적으로", "설교포인트":"일시적 감격은 지속적 신앙이 아니다"},{"원어":"ἀφίστανται (아피스탄타이)", "의미_문법":"배반하다/떠나다 - 동사 현재 중간태. 스스로 떨어져나감", "설교포인트":"배반은 외부 강요가 아니라 자발적 선택이다"}],
표2_역사적배경: [{"항목":"팔레스타인의 바위 땅", "내용":"갈릴리 지역의 많은 밭에는 얇은 흙 아래 석회암 바위가 있었다. 겉으로는 괜찮아 보이지만 뿌리가 깊이 내릴 수 없었다", "목회적활용":"겉으로는 신앙이 좋아 보이지만 내면이 얕은 신앙을 경계하라"},{"항목":"초대교회의 박해와 배교", "내용":"초대교회 시대에 로마의 박해가 시작되면 많은 신자들이 떠나갔다. 이 비유는 그러한 현실의 예언이기도 했다", "목회적활용":"신앙의 깊이는 평안할 때가 아니라 시험 속에서 드러난다"},{"항목":"기쁨의 위험성", "내용":"당시 유대 사회에서도 새로운 가르침에 열광하다가 금방 식는 경우가 많았다", "목회적활용":"첫 사랑의 열정이 성숙한 신앙으로 발전해야 한다"}],
표3_신학적의미: [{"교리":"일시적 믿음과 구원하는 믿음", "설명":"잠깐 믿는 것과 구원에 이르는 믿음은 다르다. 참된 믿음은 시험을 견디는 인내를 동반한다", "관련구절":"약 1:2-4"},{"교리":"영적 뿌리의 중요성", "설명":"뿌리는 보이지 않지만 나무를 지탱하는 핵심이다. 영적 뿌리란 말씀에 대한 깊은 이해와 확신이다", "관련구절":"엡 3:17"},{"교리":"시험의 목적", "설명":"시험은 믿음의 진위를 드러내는 역할을 한다. 시험을 통해 참된 믿음과 거짓 믿음이 구별된다", "관련구절":"벧전 1:6-7"}],
표4_예표론: [{"구분":"구약 예표", "내용":"출애굽 후 홍해를 건넌 이스라엘이 광야에서 금방 불평한 것(출 15:22-24)", "그리스도연결":"구원의 감격 후에도 시험에서 넘어질 수 있다"},{"구분":"성취", "내용":"예수님을 따르던 많은 제자가 어려운 말씀 앞에서 떠남(요 6:66)", "그리스도연결":"그리스도를 따르는 것은 감격이 아니라 결단이다"},{"구분":"완성", "내용":"끝까지 견디는 자가 구원을 얻으리라(마 24:13)", "그리스도연결":"그리스도 안에서 끝까지 인내하는 것이 참된 믿음이다"}],
표5_매튜헨리: [{"영어원문":"These are they that hear the word and receive it with joy, but their religion is merely a matter of feeling", "한국어번역":"이들은 말씀을 듣고 기쁨으로 받지만 그들의 종교는 단지 감정의 문제이다", "핵심통찰":"감정에만 기초한 신앙은 시험 앞에서 무너진다"},{"영어원문":"They have no root in themselves; their hearts are not changed, only their minds are pleased for a season", "한국어번역":"그들은 자신 안에 뿌리가 없다. 마음이 변한 것이 아니라 잠시 마음에 들었을 뿐이다", "핵심통찰":"진정한 회심은 마음의 변화이지 감정의 쾌감이 아니다"}],
표6_설교자료: [{"대지":"제목", "내용":"뿌리 없는 기쁨 — 바위 위의 신앙", "예화_적용":"감동은 있지만 뿌리가 없는 신앙의 위험성"},{"대지":"서론", "내용":"바위 위의 얇은 흙에 떨어진 씨앗은 빨리 싹이 나지만 뿌리가 깊지 못해 햇볕에 금방 시든다. 기쁨으로 말씀을 받되 뿌리가 없는 신앙이 이와 같다", "예화_적용":"부흥회에서 은혜를 받고 눈물 흘렸지만 일상으로 돌아가면 다시 예전으로 돌아가는 경험"},{"대지":"1대지: 기쁨으로 받으나 (감정적 반응)", "내용":"말씀을 들을 때 감격하고 기뻐하는 것은 좋지만 그것만으로는 부족하다", "예화_적용":"감동적인 영화를 보고 울었지만 다음 날 내용을 기억하지 못하는 것과 같다"},{"대지":"2대지: 뿌리가 없어 (깊이의 부재)", "내용":"뿌리는 말씀에 대한 깊은 이해, 기도, 순종의 훈련으로 자란다", "예화_적용":"매일 10분 묵상이 한 달에 한 번 대형 집회보다 뿌리를 깊게 한다"},{"대지":"3대지: 시험 때에 배반하는 (결국 무너짐)", "내용":"시험이 올 때 뿌리의 깊이가 드러난다. 뿌리 없는 믿음은 무너질 수밖에 없다", "예화_적용":"직장에서 신앙 때문에 불이익을 당할 때가 믿음의 진위가 드러나는 순간이다"},{"대지":"결론", "내용":"기쁨의 감격을 넘어 말씀에 뿌리를 깊이 내리는 신앙으로 성장하라. 매일의 묵상과 기도가 뿌리를 깊게 한다", "예화_적용":"폭풍에도 쓰러지지 않는 나무는 보이지 않는 곳에 깊은 뿌리가 있다"}],
표7_찬송가: [{"새찬송가":"488", "통일찬송가":"374", "제목":"나의 생명 드리니", "선정이유":"일시적 감정이 아닌 헌신의 결단"},{"새찬송가":"384", "통일찬송가":"446", "제목":"반석 위에 내가 서리", "선정이유":"반석(그리스도) 위에 뿌리내리는 신앙"},{"새찬송가":"345", "통일찬송가":"394", "제목":"예수 따라가며", "선정이유":"끝까지 따르는 신앙"},{"새찬송가":"453", "통일찬송가":"363", "제목":"내 갈 길 멀고 밤은 깊은데", "선정이유":"시험 중에도 견디는 믿음"}],
표8_상담적용: [{"상황":"신앙의 초기 열정이 식어버린 분", "성경원리":"기쁨으로 받되 뿌리가 없으면 잠깐이다", "실제적용":"감정이 아닌 말씀 묵상과 기도의 규칙적 훈련으로 뿌리를 내려라"},{"상황":"어려움이 오면 신앙을 포기하고 싶은 분", "성경원리":"시험은 믿음의 진위를 드러낸다. 시험을 견디는 것이 참된 믿음의 증거이다", "실제적용":"혼자 버티지 말고 신앙 공동체의 도움을 받으라. 함께 기도하는 동역자를 찾으라"},{"상황":"교회를 떠나려는 분", "성경원리":"배반은 자발적 선택이다. 그러나 하나님은 항상 돌아올 기회를 주신다", "실제적용":"떠나기 전에 왜 떠나려 하는지 진지하게 성찰하라. 감정인지 확신인지 구별하라"}],
표9_교차참조: [{"구절":"출 15:22-24", "연결점":"홍해를 건넌 직후 물이 없다고 원망한 이스라엘", "구분":"구약"},{"구절":"호 6:4", "연결점":"너희 인애가 아침 구름 같고 쉬 없어지는 이슬 같도다", "구분":"구약"},{"구절":"잠 12:3", "연결점":"의인의 뿌리는 옮겨지지 아니한다", "구분":"구약"},{"구절":"렘 17:8", "연결점":"물 가에 심은 나무가 뿌리를 강변에 뻗치고", "구분":"구약"},{"구절":"요 6:66", "연결점":"그 제자 중 많은 사람이 떠나가고", "구분":"신약"},{"구절":"약 1:2-4", "연결점":"시험을 만나거든 온전히 기쁘게 여기라", "구분":"신약"},{"구절":"벧전 1:6-7", "연결점":"여러 가지 시험으로 말미암아 근심하게 되나 믿음의 시련이", "구분":"신약"},{"구절":"히 3:12-14", "연결점":"살아계신 하나님에게서 떨어질까 조심하라", "구분":"신약"}]
};

pastorCommentaryData["누가복음_8_14"] = {
본문: "가시떨기에 떨어졌다는 것은 듣는 자이나 지내는 중 이생의 염려와 재리와 일락에 기운이 막혀 온전히 결실치 못하는 자요",
표1_원어분석: [{"원어":"ἀκάνθας (아칸다스)", "의미_문법":"가시떨기 - 명사. 가시나무/잡초", "설교포인트":"가시떨기는 영적 성장을 방해하는 세상의 것들이다"},{"원어":"μεριμνῶν (메림논)", "의미_문법":"염려 - 명사 복수. 불안/근심", "설교포인트":"이생의 염려가 말씀의 성장을 질식시킨다"},{"원어":"πλούτου (플루투)", "의미_문법":"재리/부 - 명사 속격. 물질적 풍요", "설교포인트":"물질에 대한 욕심이 영적 결실을 막는다"},{"원어":"ἡδονῶν (헤도논)", "의미_문법":"일락/쾌락 - 명사 복수. 쾌락/즐거움", "설교포인트":"세상의 쾌락이 영적 결실의 적이다"},{"원어":"συμπνίγονται (심프니곤타이)", "의미_문법":"기운이 막히다 - 동사 현재 수동태. 질식당하다", "설교포인트":"가시떨기에 의한 질식은 서서히 진행된다"}],
표2_역사적배경: [{"항목":"팔레스타인의 가시떨기", "내용":"팔레스타인 땅에는 다양한 종류의 가시덤불이 자라며 작물과 경쟁하여 영양분을 빼앗았다", "목회적활용":"세상의 유혹은 겉으로는 무해해 보이지만 영적 생명력을 빼앗는다"},{"항목":"이생의 삼중 위협", "내용":"염려(불안), 재리(물질욕), 일락(쾌락)은 당시나 지금이나 인간의 보편적 유혹이다", "목회적활용":"이 세 가지가 나의 신앙을 질식시키고 있지 않은지 점검하라"},{"항목":"온전히 결실치 못함", "내용":"완전히 죽는 것이 아니라 열매를 맺지 못하는 상태로 세 번째 땅의 비극이다", "목회적활용":"교회에 다니지만 열매 없는 신앙이 가장 안타까운 상태이다"}],
표3_신학적의미: [{"교리":"세속화의 위험", "설명":"가시떨기 땅은 완전한 배교가 아니라 세속화를 의미한다. 신앙은 유지하되 열매가 없는 상태", "관련구절":"딤전 6:9-10"},{"교리":"열매 없는 신앙의 문제", "설명":"하나님은 열매를 기대하신다. 열매 없는 무화과나무에 대한 예수님의 저주는 이를 보여준다", "관련구절":"요 15:2"},{"교리":"이중 충성의 불가능", "설명":"하나님과 재물을 함께 섬길 수 없다. 이생의 것들이 하나님의 자리를 차지하면 결실할 수 없다", "관련구절":"마 6:24"}],
표4_예표론: [{"구분":"구약 예표", "내용":"솔로몬이 부와 쾌락을 추구하다가 영적으로 타락한 것(왕상 11:1-8)", "그리스도연결":"세상의 풍요가 하나님에게서 멀어지게 할 수 있다"},{"구분":"성취", "내용":"부자 청년이 재물 때문에 예수님을 따르지 못함(눅 18:22-23)", "그리스도연결":"물질이 그리스도를 따르는 것을 방해할 수 있다"},{"구분":"완성", "내용":"새 하늘과 새 땅에서는 가시와 엉겅퀴가 없다(사 55:13)", "그리스도연결":"가시떨기의 저주가 완전히 제거되는 새 창조"}],
표5_매튜헨리: [{"영어원문":"The cares of this world are great hindrances to our profiting by the word of God; they choke the good seed", "한국어번역":"이 세상의 염려는 우리가 하나님의 말씀으로 유익을 얻는 것의 큰 방해물이다. 그것들이 좋은 씨앗을 질식시킨다", "핵심통찰":"세상의 염려가 말씀의 효과를 질식시키는 가장 보편적 원인이다"},{"영어원문":"Riches and pleasures are thorns that choke the word; they fill the heart, and leave no room for the word", "한국어번역":"부와 쾌락은 말씀을 질식시키는 가시이다. 마음을 가득 채워 말씀이 들어갈 자리를 남기지 않는다", "핵심통찰":"마음에 세상이 가득하면 말씀이 자랄 공간이 없다"}],
표6_설교자료: [{"대지":"제목", "내용":"가시떨기 속의 신앙 — 열매 없는 삶의 비극", "예화_적용":"교회에 다니지만 열매 없는 신앙의 위험성"},{"대지":"서론", "내용":"세 번째 땅은 가장 많은 현대 그리스도인의 모습일 수 있다. 완전히 떠나지는 않지만 열매를 맺지 못하는 신앙. 이생의 염려, 재리, 일락이 서서히 영적 생명력을 질식시킨다", "예화_적용":"서서히 끓는 물 속의 개구리처럼 세속화는 알아차리지 못하는 사이에 진행된다"},{"대지":"1대지: 이생의 염려 (불안이 질식시키다)", "내용":"먹을 것, 입을 것, 내일의 걱정이 말씀의 자리를 빼앗는다", "예화_적용":"새벽기도 시간에 걱정거리를 생각하고 있는 자신을 발견한 적이 있는가"},{"대지":"2대지: 재리의 유혹 (물질이 질식시키다)", "내용":"돈과 재물에 대한 욕심이 영적 갈급함을 대체한다", "예화_적용":"주일에도 사업 걱정을 내려놓지 못하는 것이 가시떨기의 질식이다"},{"대지":"3대지: 일락의 중독 (쾌락이 질식시키다)", "내용":"세상의 즐거움이 하나님을 즐거워하는 것을 대체한다", "예화_적용":"성경보다 넷플릭스가 더 재미있다면 가시떨기가 자라고 있는 것이다"},{"대지":"결론", "내용":"가시떨기를 뽑아내는 것은 고통스럽지만 반드시 해야 할 일이다. 우선순위를 점검하고 하나님 나라를 먼저 구하라", "예화_적용":"매주 한 가지씩 영적 성장을 방해하는 것을 정리하라"}],
표7_찬송가: [{"새찬송가":"310", "통일찬송가":"282", "제목":"세상의 헛된 신을", "선정이유":"세상의 헛된 것을 버리는 결단"},{"새찬송가":"364", "통일찬송가":"400", "제목":"내 주를 가까이 하게 함은", "선정이유":"세상보다 주님께 가까이 나아감"},{"새찬송가":"434", "통일찬송가":"321", "제목":"내 모든 시험 무거운 짐을", "선정이유":"세상의 염려와 시험을 주님께 맡김"},{"새찬송가":"288", "통일찬송가":"454", "제목":"예수 나를 위하여", "선정이유":"세상의 것을 내려놓는 헌신"}],
표8_상담적용: [{"상황":"신앙생활이 바쁜 일상에 밀려나는 분", "성경원리":"이생의 염려가 말씀을 질식시킨다", "실제적용":"하루 중 가장 먼저 하나님께 시간을 드리라. 아침 15분 묵상을 최우선으로 하라"},{"상황":"물질적 풍요 속에 영적 갈급함을 잃은 분", "성경원리":"재리가 영적 결실을 막는다. 부요할수록 영적 위험이 크다", "실제적용":"소유의 일부를 나누는 연습을 하라. 나눔이 물질의 질식에서 벗어나는 길이다"},{"상황":"세상의 즐거움에 빠져 있는 분", "성경원리":"일락이 하나님을 즐거워하는 것을 대체한다", "실제적용":"일주일에 하루는 세상의 미디어를 끊고 하나님과의 시간을 가지라"}],
표9_교차참조: [{"구절":"왕상 11:1-8", "연결점":"솔로몬이 이방 여인과 재물로 인해 하나님을 떠남", "구분":"구약"},{"구절":"전 2:10-11", "연결점":"내 눈이 원하는 것을 금하지 아니하며...다 헛되어 바람을 잡으려는 것이라", "구분":"구약"},{"구절":"시 73:3-12", "연결점":"악인의 형통함을 보고 부러워하는 시인의 고백", "구분":"구약"},{"구절":"사 55:2", "연결점":"어찌하여 양식이 아닌 것을 위하여 돈을 달아 쓰며", "구분":"구약"},{"구절":"마 6:24", "연결점":"하나님과 재물을 겸하여 섬기지 못하느니라", "구분":"신약"},{"구절":"딤전 6:9-10", "연결점":"돈을 사랑함이 일만 악의 뿌리가 되나니", "구분":"신약"},{"구절":"요일 2:15-17", "연결점":"이 세상이나 세상에 있는 것들을 사랑하지 말라", "구분":"신약"},{"구절":"눅 18:22-25", "연결점":"부자 청년이 재물 때문에 예수를 따르지 못함", "구분":"신약"}]
};

pastorCommentaryData["누가복음_8_15"] = {
본문: "좋은 땅에 있다는 것은 착하고 좋은 마음으로 말씀을 듣고 지키어 인내로 결실하는 자니라",
표1_원어분석: [{"원어":"καλῇ (칼레)", "의미_문법":"좋은/아름다운 - 형용사. 도덕적으로 선한", "설교포인트":"좋은 땅은 하나님 앞에서 준비된 마음이다"},{"원어":"καρδίᾳ καλῇ καὶ ἀγαθῇ (카르디아 칼레 카이 아가테)", "의미_문법":"착하고 좋은 마음 - 명사구. 선하고 아름다운 마음", "설교포인트":"말씀을 받는 마음의 상태가 결실을 결정한다"},{"원어":"κατέχουσιν (카테쿠신)", "의미_문법":"지키다/붙잡다 - 동사 현재. 견고히 붙잡음", "설교포인트":"말씀을 듣고 꼭 붙잡아 놓지 않는 것이 중요하다"},{"원어":"ὑπομονῇ (휘포모네)", "의미_문법":"인내 - 명사. 참고 견딤", "설교포인트":"결실에는 인내가 필수적이다"},{"원어":"καρποφοροῦσιν (카르포포루신)", "의미_문법":"결실하다 - 동사 현재. 열매를 맺다", "설교포인트":"좋은 땅은 반드시 열매를 맺는다"}],
표2_역사적배경: [{"항목":"좋은 땅의 조건", "내용":"팔레스타인에서 좋은 땅은 돌을 골라내고, 잡초를 뽑고, 깊이 갈아엎어 준비한 밭이다", "목회적활용":"좋은 마음은 자연적으로 되는 것이 아니라 준비하는 것이다"},{"항목":"백배의 결실", "내용":"당시 팔레스타인 밭의 평균 수확량은 10배 정도였다. 백배는 놀라운 풍성함을 의미한다", "목회적활용":"준비된 마음에 뿌려진 말씀은 놀라운 결실을 맺는다"},{"항목":"인내의 농업적 배경", "내용":"씨앗이 뿌려진 후 수확까지 최소 4-6개월이 걸린다. 농부에게 인내는 필수적이다", "목회적활용":"영적 결실도 시간이 필요하다. 조급해하지 말고 인내하라"}],
표3_신학적의미: [{"교리":"성화의 조건", "설명":"좋은 땅의 세 가지 특성은 듣고, 지키고, 인내하는 것이다. 이것이 성화의 핵심 요소이다", "관련구절":"히 12:1-2"},{"교리":"말씀 순종의 중요성", "설명":"듣는 것만이 아니라 지키는 것이 결실의 조건이다. 순종 없는 듣기는 무의미하다", "관련구절":"약 1:22-25"},{"교리":"인내와 결실", "설명":"인내(휘포모네)는 수동적 참음이 아니라 적극적으로 견디며 기다리는 것이다", "관련구절":"갈 6:9"}],
표4_예표론: [{"구분":"구약 예표", "내용":"여호수아와 갈렙이 인내하며 가나안 입성에 성공한 것(수 14:6-12)", "그리스도연결":"인내로 약속의 열매를 받는 모델이다"},{"구분":"성취", "내용":"예수님이 겟세마네에서 인내로 십자가의 길을 완수하심(눅 22:42)", "그리스도연결":"그리스도는 인내로 구원의 열매를 맺으신 완전한 좋은 땅이시다"},{"구분":"완성", "내용":"생명나무가 열두 가지 열매를 맺는 새 예루살렘(계 22:2)", "그리스도연결":"인내의 최종 결실은 영원한 풍성함이다"}],
표5_매튜헨리: [{"영어원문":"The good ground are the honest and good hearts, which having heard the word, keep it – they hold it fast", "한국어번역":"좋은 땅은 정직하고 선한 마음이며 말씀을 듣고 지킨다 — 그들은 굳게 붙잡는다", "핵심통찰":"말씀을 굳게 붙잡는 것이 결실의 비결이다"},{"영어원문":"They bring forth fruit with patience; in due time they reap, if they faint not", "한국어번역":"인내로 열매를 맺는다. 포기하지 않으면 때가 되면 거두리라", "핵심통찰":"포기하지 않는 인내가 결실의 핵심이다"}],
표6_설교자료: [{"대지":"제목", "내용":"좋은 땅의 비밀 — 듣고 지키어 인내로 결실", "예화_적용":"네 가지 땅 중 유일하게 열매 맺는 땅의 비결"},{"대지":"서론", "내용":"네 가지 땅의 비유에서 유일하게 열매를 맺는 땅은 좋은 땅이다. 예수님은 이 땅의 특성을 세 가지로 말씀하신다: 착하고 좋은 마음으로 듣고, 지키고, 인내로 결실하는 것이다", "예화_적용":"농부가 좋은 밭을 만들기 위해 돌을 골라내고 잡초를 뽑듯 마음도 준비해야 한다"},{"대지":"1대지: 착하고 좋은 마음으로 듣고 (준비된 마음)", "내용":"좋은 마음은 자연적으로 되는 것이 아니라 하나님 앞에서 겸손히 준비하는 것이다", "예화_적용":"예배 전 5분 기도가 마음을 좋은 땅으로 준비시킨다"},{"대지":"2대지: 지키어 (순종의 결단)", "내용":"들은 말씀을 꼭 붙잡고 실천하는 것이 지키는 것이다", "예화_적용":"설교에서 받은 한 가지 적용점을 한 주간 실천하라"},{"대지":"3대지: 인내로 결실 (끈기의 열매)", "내용":"결실에는 시간이 필요하다. 조급해하지 않고 꾸준히 말씀을 순종할 때 열매가 맺힌다", "예화_적용":"대나무는 4년간 뿌리만 내리다가 5년째 하루에 60cm씩 자란다"},{"대지":"결론", "내용":"우리의 마음을 좋은 땅으로 준비하자. 돌을 골라내고, 가시를 뽑고, 깊이 갈아엎어 말씀의 씨앗이 뿌리내릴 수 있는 마음을 만들자", "예화_적용":"오늘 한 가지 돌이나 가시를 제거하는 결단을 하라"}],
표7_찬송가: [{"새찬송가":"449", "통일찬송가":"367", "제목":"내 평생에 가는 길", "선정이유":"인내로 가는 신앙의 여정"},{"새찬송가":"377", "통일찬송가":"495", "제목":"내 갈길 멀고", "선정이유":"끝까지 인내하는 결단"},{"새찬송가":"235", "통일찬송가":"195", "제목":"말씀으로 이 세상을", "선정이유":"말씀을 듣고 지키는 삶"},{"새찬송가":"291", "통일찬송가":"259", "제목":"주의 말씀 듣고서", "선정이유":"말씀을 듣고 순종하는 결실"}],
표8_상담적용: [{"상황":"매일 성경을 읽지만 변화가 없다고 느끼는 분", "성경원리":"인내로 결실한다. 시간이 필요하다", "실제적용":"변화는 서서히 일어난다. 기록을 남겨 1년 전의 나와 비교해 보라"},{"상황":"신앙의 열매가 무엇인지 모르겠는 분", "성경원리":"좋은 땅은 반드시 열매를 맺는다. 열매는 성품, 사랑, 섬김으로 나타난다", "실제적용":"갈라디아서 5:22-23의 성령의 열매 목록을 보고 자신을 점검하라"},{"상황":"다른 사람과 비교하며 낙심하는 분", "성경원리":"결실의 양은 다를 수 있지만 좋은 땅이면 반드시 열매를 맺는다", "실제적용":"남과 비교하지 말고 어제의 나보다 오늘의 내가 더 성장했는지 보라"}],
표9_교차참조: [{"구절":"수 14:6-12", "연결점":"갈렙이 45년을 인내하며 약속의 땅을 기업으로 받음", "구분":"구약"},{"구절":"시 1:1-3", "연결점":"시냇가에 심은 나무가 시절을 좇아 과실을 맺으며", "구분":"구약"},{"구절":"사 55:10-11", "연결점":"비와 눈이 돌아가지 않고 반드시 열매를 맺게 함", "구분":"구약"},{"구절":"렘 17:7-8", "연결점":"여호와를 의뢰하는 자는 물 가에 심기운 나무 같아", "구분":"구약"},{"구절":"약 1:22-25", "연결점":"말씀을 행하는 자가 되라 듣기만 하여 자기를 속이지 말라", "구분":"신약"},{"구절":"갈 6:9", "연결점":"우리가 선을 행하되 낙심하지 말지니 때가 이르면 거두리라", "구분":"신약"},{"구절":"히 6:12", "연결점":"믿음과 오래 참음으로 약속들을 기업으로 받는 자들을 본받는 자 되게 하려 함이라", "구분":"신약"},{"구절":"요 15:4-5", "연결점":"내 안에 거하면 열매를 많이 맺으리니", "구분":"신약"}]
};

pastorCommentaryData["누가복음_8_16"] = {
본문: "누구든지 등불을 켜서 그릇으로 덮거나 평상 아래 두지 아니하고 등경 위에 놓나니 이는 들어가는 자들로 그 빛을 보게 하려 함이라",
표1_원어분석: [{"원어":"λύχνον (뤼크논)", "의미_문법":"등불 - 명사. 기름 등잔", "설교포인트":"등불은 빛을 내기 위해 존재한다"},{"원어":"ἅψας (합사스)", "의미_문법":"켜서 - 분사 과거. 불을 붙이다", "설교포인트":"하나님이 우리 안에 말씀의 빛을 켜 주셨다"},{"원어":"σκεύει (스큐에이)", "의미_문법":"그릇 - 명사. 용기/그릇", "설교포인트":"받은 빛을 감추는 것은 등불의 목적에 반하는 것이다"},{"원어":"λυχνίας (뤼크니아스)", "의미_문법":"등경/등잔대 - 명사 속격. 등을 올려놓는 대", "설교포인트":"빛은 높은 곳에 놓아 모두가 볼 수 있어야 한다"},{"원어":"βλέπωσιν (블레포신)", "의미_문법":"보게 하다 - 동사 가정법. 볼 수 있도록", "설교포인트":"빛의 목적은 다른 사람들이 보게 하는 것이다"}],
표2_역사적배경: [{"항목":"고대의 등잔", "내용":"당시 가정에서 사용한 등잔은 올리브 기름을 연료로 하는 작은 토기 등잔이었다. 한 집에 하나뿐인 귀한 빛이었다", "목회적활용":"말씀의 빛은 귀하다. 감추지 말고 나누어야 한다"},{"항목":"등경의 역할", "내용":"등경은 등잔을 높이 올려놓아 방 전체를 밝히는 역할을 했다. 낮은 곳에 두면 빛의 효과가 줄어들었다", "목회적활용":"빛을 가장 효과적으로 비추는 자리에 놓으라"},{"항목":"비유의 연결", "내용":"씨 뿌리는 자의 비유 직후에 등불 비유를 말씀하신 것은 말씀을 받은 자의 책임을 강조하기 위함이다", "목회적활용":"말씀을 받은 자는 그 빛을 세상에 비춰야 할 책임이 있다"}],
표3_신학적의미: [{"교리":"빛으로서의 그리스도인", "설명":"말씀을 받은 자는 세상의 빛이 되어야 한다. 빛을 감추는 것은 하나님의 뜻에 반하는 것이다", "관련구절":"마 5:14-16"},{"교리":"복음 전파의 사명", "설명":"등불의 목적이 비추는 것이듯 말씀을 받은 자의 사명은 복음을 전하는 것이다", "관련구절":"행 1:8"},{"교리":"하나님의 영광을 드러냄", "설명":"빛은 자기를 위해서가 아니라 다른 사람들이 볼 수 있도록 존재한다", "관련구절":"사 60:1-3"}],
표4_예표론: [{"구분":"구약 예표", "내용":"성막의 금등대가 끊임없이 빛을 비추었던 것(출 27:20-21)", "그리스도연결":"하나님의 임재의 빛은 감추어져서는 안 된다"},{"구분":"성취", "내용":"예수님이 '나는 세상의 빛이라'고 선언하심(요 8:12)", "그리스도연결":"그리스도는 세상을 비추는 참된 빛이시다"},{"구분":"완성", "내용":"새 예루살렘에는 해나 달이 필요 없고 하나님의 영광이 빛이 됨(계 21:23)", "그리스도연결":"궁극적으로 모든 빛의 근원은 하나님이시다"}],
표5_매튜헨리: [{"영어원문":"Those who are good themselves must do good to others; those who have received the gift must minister the same", "한국어번역":"스스로 선한 자는 다른 사람에게도 선을 행해야 한다. 은사를 받은 자는 그것으로 섬겨야 한다", "핵심통찰":"받은 은혜는 나누어야 할 책임이 있다"},{"영어원문":"The candle was not lighted to be concealed; the truths of God are not to be buried, but to be published", "한국어번역":"등불은 감추기 위해 켜진 것이 아니다. 하나님의 진리는 묻어두는 것이 아니라 드러내는 것이다", "핵심통찰":"진리는 드러내기 위해 주어진 것이다"}],
표6_설교자료: [{"대지":"제목", "내용":"등경 위의 등불 — 받은 빛을 비추라", "예화_적용":"말씀을 받은 자는 세상에 빛을 비추어야 한다"},{"대지":"서론", "내용":"아무도 등불을 켜서 그릇으로 덮지 않는다. 등불은 비추기 위해 존재한다. 마찬가지로 말씀을 받은 우리는 그 빛을 세상에 비추어야 한다", "예화_적용":"정전 때 촛불 하나가 온 방을 밝힌다. 작은 빛도 어둠 속에서 큰 역할을 한다"},{"대지":"1대지: 등불을 켜서 (하나님이 주신 빛)", "내용":"등불을 켜신 분은 하나님이시다. 우리 안에 말씀의 빛을 켜 주셨다", "예화_적용":"내가 스스로 빛이 된 것이 아니라 하나님이 빛을 켜 주신 것이다"},{"대지":"2대지: 그릇으로 덮지 말라 (감추지 말라)", "내용":"두려움, 게으름, 세상의 눈치로 빛을 감추는 것은 하나님의 뜻에 반하는 것이다", "예화_적용":"직장에서 신앙을 숨기는 것이 그릇으로 덮는 것이다"},{"대지":"3대지: 등경 위에 놓으라 (적극적으로 비추라)", "내용":"등경 위에 놓는다는 것은 가장 효과적으로 빛을 비추는 자리에 놓는 것이다", "예화_적용":"내가 있는 자리가 빛을 비추는 등경이다. 가정, 직장, 학교에서 빛을 비추라"},{"대지":"결론", "내용":"하나님이 켜 주신 빛을 감추지 말고 세상에 비추라. 우리의 삶이 복음의 등경이 되어 사람들이 하나님의 영광을 보게 하자", "예화_적용":"이번 주 한 사람에게 복음의 빛을 비추는 실천을 하라"}],
표7_찬송가: [{"새찬송가":"534", "통일찬송가":"490", "제목":"주의 참된 제자 되어", "선정이유":"세상에서 빛을 비추는 제자의 삶"},{"새찬송가":"365", "통일찬송가":"398", "제목":"가서 복음을 전하여라", "선정이유":"받은 빛을 전하는 사명"},{"새찬송가":"272", "통일찬송가":"232", "제목":"이 세상의 빛이신 주", "선정이유":"세상의 빛이신 주님"},{"새찬송가":"513", "통일찬송가":"478", "제목":"비둘기같이 온유한", "선정이유":"빛을 비추는 삶의 성품"}],
표8_상담적용: [{"상황":"전도가 두려운 분", "성경원리":"등불은 감추기 위해 켜진 것이 아니다. 빛을 비추는 것이 등불의 존재 이유이다", "실제적용":"말로 하는 전도가 어려우면 삶으로 먼저 빛을 비추라. 친절, 사랑, 섬김이 전도이다"},{"상황":"신앙을 숨기며 사는 분", "성경원리":"그릇으로 덮는 것은 하나님의 뜻에 반하는 것이다", "실제적용":"작은 것부터 시작하라. 식사 전 기도부터 자연스럽게 시작하라"},{"상황":"작은 교회에서 영향력이 없다고 느끼는 분", "성경원리":"작은 등불 하나가 온 방을 밝힌다", "실제적용":"내가 있는 작은 자리가 빛을 비추는 귀한 등경이다. 그 자리에서 최선을 다하라"}],
표9_교차참조: [{"구절":"출 27:20-21", "연결점":"순결한 올리브 기름으로 등을 계속 켜둘지니라", "구분":"구약"},{"구절":"사 60:1-3", "연결점":"일어나라 빛을 발하라 이는 네 빛이 이르렀고", "구분":"구약"},{"구절":"잠 4:18", "연결점":"의인의 길은 돋는 햇살 같아서", "구분":"구약"},{"구절":"단 12:3", "연결점":"지혜 있는 자는 궁창의 빛과 같이 빛날 것이며", "구분":"구약"},{"구절":"마 5:14-16", "연결점":"너희는 세상의 빛이라 산 위에 있는 동네가 숨기지 못할 것이요", "구분":"신약"},{"구절":"요 8:12", "연결점":"나는 세상의 빛이니 나를 따르는 자는 어둠에 다니지 아니하고", "구분":"신약"},{"구절":"빌 2:15", "연결점":"이 세대 가운데서 그들에게 빛들로 나타나되", "구분":"신약"},{"구절":"엡 5:8", "연결점":"너희가 전에는 어둠이더니 이제는 주 안에서 빛이라", "구분":"신약"}]
};

pastorCommentaryData["누가복음_8_17"] = {
본문: "숨은 것이 장차 드러나지 아니할 것이 없고 감추인 것이 장차 알려지고 나타나지 않을 것이 없느니라",
표1_원어분석: [{"원어":"κρυπτόν (크뤼프톤)", "의미_문법":"숨은 것 - 형용사 중성. 감추어진 것", "설교포인트":"하나님 앞에서 숨길 수 있는 것은 아무것도 없다"},{"원어":"φανερόν (파네론)", "의미_문법":"드러나다 - 형용사. 분명히 보이는", "설교포인트":"모든 숨은 것은 반드시 드러나게 된다"},{"원어":"ἀπόκρυφον (아포크뤼폰)", "의미_문법":"감추인 것 - 형용사. 비밀스러운", "설교포인트":"비밀도 때가 되면 알려지게 된다"},{"원어":"γνωσθῇ (그노스데)", "의미_문법":"알려지다 - 동사 가정법 수동태 과거. 인식되다", "설교포인트":"하나님은 모든 것을 알고 계시고 드러내실 것이다"}],
표2_역사적배경: [{"항목":"유대 격언의 활용", "내용":"숨은 것이 드러난다는 표현은 당시 유대 지혜 전통에서도 사용되던 격언이었다. 예수님은 이를 영적 진리로 확장하셨다", "목회적활용":"진리는 반드시 드러난다. 거짓은 일시적이지만 진리는 영원하다"},{"항목":"등불 비유와의 연결", "내용":"앞의 등불 비유에 이어 빛과 드러남의 주제가 계속된다. 빛이 어둠을 드러내듯 하나님의 말씀이 숨은 것을 드러낸다", "목회적활용":"말씀의 빛 앞에서 모든 것이 드러나므로 정직하게 살라"},{"항목":"비밀 제자도의 경고", "내용":"당시 예수를 믿으면서도 공개적으로 고백하지 않는 사람들이 있었다(니고데모 등)", "목회적활용":"숨은 신앙은 결국 드러나게 된다. 처음부터 당당히 고백하라"}],
표3_신학적의미: [{"교리":"하나님의 전지성", "설명":"하나님 앞에서 숨길 수 있는 것은 없다. 모든 것이 벌거벗은 채로 드러나있다", "관련구절":"히 4:13"},{"교리":"최후 심판의 공개성", "설명":"마지막 날에 모든 숨은 일이 드러날 것이다. 선한 것도 악한 것도 모두 심판받는다", "관련구절":"전 12:14"},{"교리":"복음의 보편적 전파", "설명":"지금은 숨겨진 듯한 복음의 진리가 온 세상에 드러나게 될 것이다", "관련구절":"마 10:26-27"}],
표4_예표론: [{"구분":"구약 예표", "내용":"아간이 숨긴 전리품이 결국 드러난 것(수 7:19-21)", "그리스도연결":"하나님 앞에서 숨길 수 있는 죄는 없다"},{"구분":"성취", "내용":"예수님이 바리새인들의 외식을 드러내심(눅 12:1-3)", "그리스도연결":"그리스도는 모든 위선을 드러내시는 진리의 빛이시다"},{"구분":"완성", "내용":"최후 심판에서 모든 것이 드러남(계 20:12)", "그리스도연결":"그리스도의 심판대 앞에서 모든 숨은 것이 밝혀진다"}],
표5_매튜헨리: [{"영어원문":"Whatever is hid shall be made manifest; hypocrisy will be unmasked, and secret wickedness brought to light", "한국어번역":"숨겨진 것은 무엇이든 드러날 것이다. 위선은 벗겨지고 비밀의 악은 빛 가운데 나올 것이다", "핵심통찰":"위선은 반드시 벗겨지게 되어 있다"},{"영어원문":"This may also be understood as an encouragement: the treasures of wisdom that are now hidden in the word shall be made known to those who diligently search", "한국어번역":"이것은 격려로도 이해할 수 있다. 말씀에 숨겨진 지혜의 보화가 부지런히 찾는 자에게 알려질 것이다", "핵심통찰":"말씀에 숨겨진 진리가 부지런한 자에게 드러난다"}],
표6_설교자료: [{"대지":"제목", "내용":"숨은 것이 드러나는 날 — 빛 앞에 선 인생", "예화_적용":"하나님 앞에서 숨길 수 있는 것은 아무것도 없다"},{"대지":"서론", "내용":"우리는 많은 것을 숨기며 살아간다. 그러나 예수님은 선언하신다. 숨은 것이 드러나지 않을 것이 없다고. 이것은 경고이자 동시에 소망이다", "예화_적용":"CCTV가 없는 곳에서도 하나님은 보고 계신다"},{"대지":"1대지: 숨은 죄가 드러남 (경고)", "내용":"감추고 있는 죄, 비밀의 죄가 반드시 드러나게 된다", "예화_적용":"아간처럼 숨긴 것이 결국 온 공동체에 드러났다"},{"대지":"2대지: 숨은 의가 드러남 (위로)", "내용":"세상이 알아주지 않는 선행, 눈물의 기도도 하나님은 알고 계시고 드러내실 것이다", "예화_적용":"아무도 모르게 섬기는 봉사도 하나님이 기억하신다"},{"대지":"3대지: 숨은 진리가 드러남 (소망)", "내용":"지금은 이해하지 못하는 하나님의 뜻도 때가 되면 드러난다", "예화_적용":"고난의 이유를 지금은 모르지만 때가 되면 그 뜻을 알게 된다"},{"대지":"결론", "내용":"숨은 것이 드러나는 날을 두려워하지 말고 오히려 빛 가운데 살자. 정직한 삶이 가장 자유로운 삶이다", "예화_적용":"오늘 하루를 하나님 앞에 완전히 드러내놓고 살아보라"}],
표7_찬송가: [{"새찬송가":"488", "통일찬송가":"374", "제목":"나의 생명 드리니", "선정이유":"하나님 앞에 모든 것을 드러내는 헌신"},{"새찬송가":"279", "통일찬송가":"253", "제목":"주님의 뜻을 이루소서", "선정이유":"숨은 하나님의 뜻이 드러나기를 소망"},{"새찬송가":"330", "통일찬송가":"295", "제목":"예수로 나의 구주 삼고", "선정이유":"빛 가운데 사는 정직한 신앙"},{"새찬송가":"496", "통일찬송가":"377", "제목":"하나님은 우리의 도움이시라", "선정이유":"모든 것을 아시는 하나님을 신뢰"}],
표8_상담적용: [{"상황":"숨기고 있는 죄로 괴로워하는 분", "성경원리":"숨은 것은 반드시 드러난다. 차라리 스스로 고백하는 것이 낫다", "실제적용":"신뢰할 수 있는 목사나 신앙의 동역자에게 고백하라. 고백이 치유의 시작이다"},{"상황":"선행이 인정받지 못해 낙심하는 분", "성경원리":"숨은 의도 하나님이 드러내신다. 하나님은 숨은 중에 보시고 갚으실 것이다", "실제적용":"사람의 인정이 아니라 하나님의 인정을 구하라. 때가 되면 드러나실 것이다"},{"상황":"하나님의 뜻을 이해하지 못하는 분", "성경원리":"감추인 것이 때가 되면 알려진다", "실제적용":"지금 이해하지 못해도 믿음으로 기다리라. 하나님의 뜻은 때가 되면 분명해진다"}],
표9_교차참조: [{"구절":"수 7:19-21", "연결점":"아간이 숨긴 전리품이 드러나 심판받음", "구분":"구약"},{"구절":"전 12:14", "연결점":"하나님은 모든 행위와 모든 은밀한 일을 심판하시리니", "구분":"구약"},{"구절":"시 139:1-4", "연결점":"여호와여 주께서 나를 감찰하시고 아셨나이다", "구분":"구약"},{"구절":"렘 23:24", "연결점":"사람이 내게 보이지 않게 숨을 수 있겠느냐", "구분":"구약"},{"구절":"마 10:26-27", "연결점":"감추인 것이 드러나지 않을 것이 없고 숨은 것이 알려지지 않을 것이 없느니라", "구분":"신약"},{"구절":"히 4:13", "연결점":"지으신 것이 하나도 그 앞에 나타나지 않음이 없고", "구분":"신약"},{"구절":"고전 4:5", "연결점":"때가 이르면 어둠에 감추인 것들을 드러내고", "구분":"신약"},{"구절":"롬 2:16", "연결점":"하나님이 사람들의 은밀한 것을 심판하시는 그 날이라", "구분":"신약"}]
};

pastorCommentaryData["누가복음_8_18"] = {
본문: "그러므로 너희가 어떻게 듣는가 스스로 삼가라 누구든지 있는 자는 받겠고 없는 자는 그 있는 줄로 아는 것까지 빼앗기리라 하시니라",
표1_원어분석: [{"원어":"βλέπετε (블레페테)", "의미_문법":"삼가라/조심하라 - 동사 명령형 현재. 계속 주의하라", "설교포인트":"듣는 것에 대한 지속적인 경각심이 필요하다"},{"원어":"πῶς (포스)", "의미_문법":"어떻게 - 부사. 방법/태도", "설교포인트":"무엇을 듣느냐보다 어떻게 듣느냐가 중요하다"},{"원어":"ἀκούετε (아쿠에테)", "의미_문법":"듣다 - 동사 현재. 계속 듣는 행위", "설교포인트":"듣는 태도가 영적 성장을 결정한다"},{"원어":"δοκεῖ ἔχειν (도케이 에케인)", "의미_문법":"있는 줄로 아는 것 - 동사구. 가지고 있다고 생각하는 것", "설교포인트":"실제로 가진 것이 아니라 가졌다고 착각하는 것도 빼앗긴다"}],
표2_역사적배경: [{"항목":"유대 교육의 듣기 전통", "내용":"유대 교육은 쉐마(듣다)를 중심으로 이루어졌다. 듣는 것은 단순한 청각이 아니라 순종을 포함하는 행위였다", "목회적활용":"성경의 '듣다'는 순종을 포함한다. 듣기만 하고 행하지 않으면 듣지 않은 것과 같다"},{"항목":"있는 자와 없는 자의 원리", "내용":"당시 사회에서도 부익부 빈익빈의 원리가 작용했다. 예수님은 이를 영적 영역에 적용하셨다", "목회적활용":"영적 세계에서도 충실한 자에게 더 주시고, 게으른 자에게서 빼앗으시는 원리가 있다"},{"항목":"자기 기만의 위험", "내용":"있는 줄로 아는 것은 실제로 없는 것이다. 자기 기만이 가장 위험하다", "목회적활용":"자신의 영적 상태를 정직하게 점검하라"}],
표3_신학적의미: [{"교리":"듣기의 책임", "설명":"어떻게 듣느냐에 따라 주어지기도 하고 빼앗기기도 한다. 듣기는 수동적 행위가 아니라 책임이 따르는 행위이다", "관련구절":"약 1:19-22"},{"교리":"영적 성장의 법칙", "설명":"충실하게 말씀을 듣고 행하는 자에게는 더 주시고, 그렇지 않은 자에게서는 빼앗으신다", "관련구절":"마 25:29"},{"교리":"자기 기만의 위험", "설명":"가지고 있다고 착각하는 것까지 빼앗긴다. 형식적 신앙의 위험을 경고한다", "관련구절":"계 3:17"}],
표4_예표론: [{"구분":"구약 예표", "내용":"사울 왕이 왕위를 가지고 있었으나 불순종으로 빼앗긴 것(삼상 15:26-28)", "그리스도연결":"주어진 것도 불순종하면 빼앗기게 된다"},{"구분":"성취", "내용":"이스라엘이 하나님 나라를 가지고 있었으나 열매 맺지 못해 이방인에게로 넘어감(마 21:43)", "그리스도연결":"하나님 나라의 특권도 열매 없으면 빼앗길 수 있다"},{"구분":"완성", "내용":"충성된 종에게 '잘하였다 착하고 충성된 종아'라고 칭찬하시고 더 주심(마 25:21)", "그리스도연결":"최종적으로 충성된 자에게 영원한 상급이 주어진다"}],
표5_매튜헨리: [{"영어원문":"Take heed how ye hear; not only what ye hear, but how ye hear – with what attention, intention, and retention", "한국어번역":"어떻게 듣는가 삼가라. 무엇을 듣느냐뿐 아니라 어떻게 듣느냐 — 얼마나 주의를 기울이고, 의도를 가지고, 마음에 담느냐", "핵심통찰":"주의, 의도, 기억의 세 가지가 바른 듣기의 요소이다"},{"영어원문":"He that has, to him shall be given; he that uses what he has for God's glory shall have more", "한국어번역":"가진 자에게 주어질 것이다. 가진 것을 하나님의 영광을 위해 사용하는 자에게 더 주실 것이다", "핵심통찰":"받은 것을 충실히 사용하는 자에게 더 많이 주어진다"}],
표6_설교자료: [{"대지":"제목", "내용":"어떻게 듣는가 — 듣기의 영적 법칙", "예화_적용":"같은 설교를 들어도 결과가 다른 이유"},{"대지":"서론", "내용":"같은 교회에서 같은 설교를 들어도 어떤 사람은 변화되고 어떤 사람은 무덤덤하다. 예수님은 그 차이가 '어떻게 듣느냐'에 있다고 말씀하신다", "예화_적용":"같은 수업을 들어도 집중하는 학생과 졸고 있는 학생의 성적이 다르다"},{"대지":"1대지: 어떻게 듣는가 (듣기의 태도)", "내용":"말씀을 듣는 태도가 결실을 결정한다. 겸손하게, 갈급하게, 순종할 준비를 하고 들으라", "예화_적용":"예배 전 5분의 기도가 듣기의 태도를 준비시킨다"},{"대지":"2대지: 있는 자에게 더 주심 (충성의 보상)", "내용":"들은 말씀을 실천하는 자에게 더 깊은 깨달음이 주어진다", "예화_적용":"말씀 한 구절을 순종하면 더 많은 말씀이 열린다"},{"대지":"3대지: 있는 줄로 아는 것까지 빼앗김 (자기 기만의 위험)", "내용":"형식적으로만 듣는 사람은 가지고 있다고 착각하는 것마저 잃게 된다", "예화_적용":"20년 교회를 다녔지만 실제로는 영적으로 빈손인 경우가 있다"},{"대지":"결론", "내용":"오늘 이 시간 어떻게 듣고 있는지 스스로 점검하라. 들은 것을 실천하는 한 걸음이 더 큰 은혜의 문을 연다", "예화_적용":"오늘 설교에서 한 가지를 가져가 이번 주에 실천하라"}],
표7_찬송가: [{"새찬송가":"291", "통일찬송가":"259", "제목":"주의 말씀 듣고서", "선정이유":"말씀을 듣고 실천하는 삶"},{"새찬송가":"230", "통일찬송가":"241", "제목":"성경의 귀한 말씀", "선정이유":"말씀 듣기의 소중함"},{"새찬송가":"405", "통일찬송가":"332", "제목":"나 같은 죄인 살리신", "선정이유":"은혜에 대한 겸손한 반응"},{"새찬송가":"382", "통일찬송가":"395", "제목":"어디든지 예수 나를 이끌면", "선정이유":"말씀에 순종하는 결단"}],
표8_상담적용: [{"상황":"오랜 신앙생활에도 영적 성장이 없다고 느끼는 분", "성경원리":"어떻게 듣느냐가 중요하다. 형식적 듣기는 성장을 가져오지 않는다", "실제적용":"설교를 들을 때 한 가지 적용점을 반드시 찾고 그 주간에 실천하라"},{"상황":"은사가 점점 줄어드는 것 같은 분", "성경원리":"사용하지 않으면 빼앗긴다. 충실히 사용하면 더 주어진다", "실제적용":"작은 은사라도 매주 사용하라. 기도, 전도, 섬김 중 하나를 선택하여 꾸준히 하라"},{"상황":"신앙에 자만하는 분", "성경원리":"있는 줄로 아는 것까지 빼앗기리라. 자만은 영적 몰락의 시작이다", "실제적용":"겸손히 자신의 영적 상태를 점검하라. 다른 사람의 믿음에서 배우라"}],
표9_교차참조: [{"구절":"삼상 15:26-28", "연결점":"사울이 불순종으로 왕위를 빼앗김", "구분":"구약"},{"구절":"신 6:4-9", "연결점":"이스라엘아 들으라 — 쉐마 명령", "구분":"구약"},{"구절":"잠 8:33-34", "연결점":"훈계를 듣고 지혜롭게 되라 버리지 말라", "구분":"구약"},{"구절":"사 6:9-10", "연결점":"듣기는 들어도 깨닫지 못하며", "구분":"구약"},{"구절":"마 25:29", "연결점":"무릇 있는 자는 받아 풍족하게 되고 없는 자는 그 있는 것까지 빼앗기리라", "구분":"신약"},{"구절":"약 1:19-22", "연결점":"듣기는 속히 하고 말하기는 더디 하고", "구분":"신약"},{"구절":"계 3:17", "연결점":"네가 부요하다 하나 사실은 곤고하고 불쌍하고 가난하고", "구분":"신약"},{"구절":"히 2:1", "연결점":"들은 것에 더욱 유념함으로 혹 흘러 떠내려가지 않도록 하자", "구분":"신약"}]
};

pastorCommentaryData["누가복음_8_19"] = {
본문: "예수의 모친과 그 동생들이 왔으나 무리를 인하여 가까이 하지 못하거늘",
표1_원어분석: [{"원어":"μήτηρ (메테르)", "의미_문법":"모친/어머니 - 명사. 생모", "설교포인트":"예수님의 모친 마리아도 예수님께 나아오려 했다"},{"원어":"ἀδελφοί (아델포이)", "의미_문법":"동생들/형제들 - 명사 복수. 혈육 형제", "설교포인트":"예수님에게는 육신의 형제들이 있었다"},{"원어":"ὄχλον (오클론)", "의미_문법":"무리 - 명사. 군중", "설교포인트":"많은 무리가 예수님 주위를 둘러싸고 있었다"},{"원어":"συντυχεῖν (신튀케인)", "의미_문법":"만나다/가까이하다 - 동사 부정사. 접근하다", "설교포인트":"육적 관계로는 예수님께 가까이 할 수 없었다"}],
표2_역사적배경: [{"항목":"예수님의 형제들", "내용":"마가복음 6:3에 따르면 야고보, 요세, 유다, 시몬이 예수님의 동생들이었다. 공생애 중에는 예수님을 믿지 않았다(요 7:5)", "목회적활용":"가장 가까운 가족도 처음부터 믿은 것은 아니었다. 가족 전도에 인내가 필요하다"},{"항목":"가족의 방문 의도", "내용":"마가복음 3:21에 따르면 가족들은 예수님이 미쳤다고 생각하여 붙잡으러 온 것이다", "목회적활용":"하나님의 일을 하는 자를 세상은 이해하지 못할 수 있다"},{"항목":"무리의 장벽", "내용":"많은 무리가 예수님을 둘러싸고 있어 가족조차 접근하지 못했다", "목회적활용":"영적 갈급함으로 모인 무리 앞에서 육적 관계는 우선순위가 될 수 없다"}],
표3_신학적의미: [{"교리":"육적 관계와 영적 관계", "설명":"육적 가족 관계가 영적 관계보다 우선할 수 없다는 것을 보여주는 장면", "관련구절":"마 10:37"},{"교리":"예수님의 참 인성", "설명":"예수님에게 어머니와 형제가 있었다는 것은 참된 인간이셨음을 보여준다", "관련구절":"갈 4:4"},{"교리":"말씀 사역의 우선순위", "설명":"예수님은 가족의 방문보다 말씀 사역을 우선하셨다", "관련구절":"눅 2:49"}],
표4_예표론: [{"구분":"구약 예표", "내용":"레위 지파가 가족보다 하나님의 뜻을 우선한 것(신 33:9)", "그리스도연결":"하나님의 일은 혈연보다 우선한다"},{"구분":"성취", "내용":"예수님이 가족의 방문보다 말씀 사역을 우선하심", "그리스도연결":"그리스도는 아버지의 뜻을 가장 먼저 행하셨다"},{"구분":"완성", "내용":"하나님 나라에서는 영적 가족이 궁극적 가족이 됨(엡 2:19)", "그리스도연결":"그리스도 안에서의 가족이 영원한 가족이다"}],
표5_매튜헨리: [{"영어원문":"Christ's mother and brethren came to speak with him, but could not come at him for the press", "한국어번역":"그리스도의 모친과 형제들이 말씀하려고 왔으나 무리 때문에 가까이 할 수 없었다", "핵심통찰":"육적 관계만으로는 예수님께 접근할 수 없다"},{"영어원문":"Those who think themselves nearest to Christ by outward relation may yet be far from him by inward disposition", "한국어번역":"외적 관계로 그리스도에게 가장 가깝다고 생각하는 자들이 내적 성향으로는 멀리 있을 수 있다", "핵심통찰":"외적 친밀함이 영적 친밀함을 보장하지 않는다"}],
표6_설교자료: [{"대지":"제목", "내용":"가까이 하지 못하거늘 — 육적 관계의 한계", "예화_적용":"혈연만으로는 예수님께 가까이 할 수 없다"},{"대지":"서론", "내용":"예수님의 어머니와 형제들이 찾아왔다. 그러나 무리 때문에 가까이 하지 못했다. 이 단순한 장면 속에 깊은 영적 진리가 숨어있다", "예화_적용":"교회에 오래 다닌 것만으로 예수님과 가까운 것은 아니다"},{"대지":"1대지: 가족이 찾아옴 (육적 관계의 시도)", "내용":"예수님의 어머니와 형제들이 찾아왔다. 그러나 이들의 의도는 예수님의 사역을 이해한 것이 아니었다", "예화_적용":"가장 가까운 가족도 하나님의 일을 이해하지 못할 수 있다"},{"대지":"2대지: 무리로 인해 가까이 못함 (장벽의 의미)", "내용":"무리는 영적 갈급함으로 모인 사람들이다. 이들이 육적 관계보다 예수님께 더 가까이 있었다", "예화_적용":"핏줄이 아니라 영적 갈급함이 예수님과의 거리를 결정한다"},{"대지":"3대지: 육적 관계의 한계 (혈연을 넘어서)", "내용":"육적 관계만으로는 예수님의 사역에 참여할 수 없다. 영적 관계가 필요하다", "예화_적용":"목사 자녀라고 자동으로 구원받는 것은 아니다"},{"대지":"결론", "내용":"예수님께 가까이 하는 길은 혈연이 아니라 믿음과 말씀 순종이다. 오늘 말씀 앞에 나아와 영적으로 가까이 하자", "예화_적용":"매일 기도와 말씀으로 예수님께 가까이 나아가라"}],
표7_찬송가: [{"새찬송가":"364", "통일찬송가":"400", "제목":"내 주를 가까이 하게 함은", "선정이유":"주님께 가까이 나아가는 소망"},{"새찬송가":"316", "통일찬송가":"266", "제목":"주의 사랑 안에 거하라", "선정이유":"주님과의 영적 친밀함"},{"새찬송가":"394", "통일찬송가":"456", "제목":"예수 더 알기 원하네", "선정이유":"예수님을 더 깊이 알고자 하는 갈망"},{"새찬송가":"312", "통일찬송가":"283", "제목":"주 하나님 앞에", "선정이유":"하나님 앞에 나아오는 예배"}],
표8_상담적용: [{"상황":"가족이 신앙을 이해하지 못하는 분", "성경원리":"예수님의 가족도 처음에는 이해하지 못했다", "실제적용":"인내하며 사랑으로 대하라. 예수님의 형제 야고보도 나중에 믿게 되었다"},{"상황":"신앙인 가정에서 자란 것에 안주하는 분", "성경원리":"육적 관계만으로는 예수님께 가까이 할 수 없다", "실제적용":"부모님의 신앙이 아닌 나만의 신앙을 세우라. 개인적 결단이 필요하다"},{"상황":"사역 때문에 가족과 갈등이 있는 분", "성경원리":"예수님도 가족의 오해를 경험하셨다", "실제적용":"사역과 가족 사이의 균형을 찾되, 하나님의 뜻을 먼저 구하라"}],
표9_교차참조: [{"구절":"신 33:9", "연결점":"레위가 자기 부모에게 대하여 그를 알지 못한다 하며", "구분":"구약"},{"구절":"삼상 2:27-29", "연결점":"엘리가 아들보다 하나님을 더 중히 여기지 않음", "구분":"구약"},{"구절":"시 27:10", "연결점":"내 부모가 나를 버릴지라도 여호와는 나를 영접하시리이다", "구분":"구약"},{"구절":"미 7:6", "연결점":"아들이 아비를 멸시하며 딸이 어미를 대적하며", "구분":"구약"},{"구절":"요 7:5", "연결점":"그 형제들도 예수를 믿지 아니하더라", "구분":"신약"},{"구절":"마 10:37", "연결점":"아비나 어미를 나보다 더 사랑하는 자는 내게 합당치 아니하고", "구분":"신약"},{"구절":"막 3:21", "연결점":"예수의 친속들이 미쳤다 하고 붙잡으러 나오니라", "구분":"신약"},{"구절":"갈 4:4", "연결점":"때가 차매 하나님이 그 아들을 보내사 여자에게서 나게 하시고", "구분":"신약"}]
};

pastorCommentaryData["누가복음_8_20"] = {
본문: "혹이 고하되 당신의 모친과 동생들이 당신을 보려고 밖에 섰나이다 하니",
표1_원어분석: [{"원어":"ἀπηγγέλη (아팡겔레)", "의미_문법":"고하다/전하다 - 동사 과거 수동태. 보고되다", "설교포인트":"누군가가 예수님께 가족의 도착을 알렸다"},{"원어":"ἑστήκασιν (헤스테카신)", "의미_문법":"서 있다 - 동사 완료. 계속 서서 기다리고 있다", "설교포인트":"밖에 서서 기다리는 것은 아직 안으로 들어오지 못한 상태이다"},{"원어":"ἔξω (엑소)", "의미_문법":"밖에 - 부사. 바깥에", "설교포인트":"안과 밖의 구분이 영적 의미를 가진다"},{"원어":"ἰδεῖν (이데인)", "의미_문법":"보다/만나다 - 동사 부정사. 만나기를 원하다", "설교포인트":"보고 싶다는 것은 관계를 갈망하는 것이다"}],
표2_역사적배경: [{"항목":"중재자의 역할", "내용":"당시 랍비에게 메시지를 전달하려면 중간에 누군가가 전해야 했다. 가르치는 중에 방해하는 것은 무례한 일이었다", "목회적활용":"하나님의 말씀이 선포되는 시간은 존중받아야 한다"},{"항목":"안과 밖의 구분", "내용":"예수님의 가르침을 듣기 위해 안에 모인 무리와 밖에 서 있는 가족의 대조가 의미심장하다", "목회적활용":"교회 안에 있다고 영적으로 가까운 것이 아니고, 밖에 있다고 멀리 있는 것이 아니다"},{"항목":"기다림의 모습", "내용":"예수님의 가족이 밖에서 기다리고 있었다는 것은 당시의 상황이 매우 붐볐음을 보여준다", "목회적활용":"예수님을 만나려면 때로는 기다림의 인내가 필요하다"}],
표3_신학적의미: [{"교리":"영적 안과 밖", "설명":"물리적으로 밖에 있는 것이 영적 상태를 상징한다. 말씀을 듣는 자리 안에 있는 것이 중요하다", "관련구절":"계 3:20"},{"교리":"중보의 필요", "설명":"누군가가 가족의 도착을 예수님께 알린 것처럼, 중보자의 역할이 중요하다", "관련구절":"딤전 2:5"},{"교리":"접근의 조건", "설명":"예수님께 접근하는 것은 혈연이 아니라 말씀을 듣고자 하는 태도에 의해 결정된다", "관련구절":"히 10:19-22"}],
표4_예표론: [{"구분":"구약 예표", "내용":"모세가 하나님의 임재 앞에 들어갈 때 백성은 밖에 서 있어야 했던 것(출 34:29-35)", "그리스도연결":"하나님의 임재 안으로 들어가는 것은 특별한 은혜이다"},{"구분":"성취", "내용":"예수님이 믿음으로 나아오는 자를 가족보다 더 가까운 관계로 받아주심", "그리스도연결":"그리스도 안에서 누구나 하나님의 가족이 될 수 있다"},{"구분":"완성", "내용":"새 예루살렘의 문이 열려있어 누구든 들어올 수 있음(계 21:25)", "그리스도연결":"궁극적으로 모든 장벽이 제거되고 하나님의 임재 안에 거하게 된다"}],
표5_매튜헨리: [{"영어원문":"It was told Christ that his mother and his brethren stood without, desiring to see him", "한국어번역":"그리스도에게 그의 모친과 형제가 밖에 서서 만나기를 원한다고 전해졌다", "핵심통찰":"밖에 서 있다는 것은 아직 안으로 들어오지 못한 상태를 나타낸다"},{"영어원문":"They who are without, while the word of God is preaching within, are in a dangerous position", "한국어번역":"하나님의 말씀이 안에서 선포되는 동안 밖에 있는 자들은 위험한 위치에 있다", "핵심통찰":"말씀이 선포되는 자리 안에 들어와야 한다"}],
표6_설교자료: [{"대지":"제목", "내용":"밖에 서 있는 사람들 — 안과 밖의 차이", "예화_적용":"말씀의 자리 안에 있느냐 밖에 있느냐가 중요하다"},{"대지":"서론", "내용":"예수님의 어머니와 형제들이 밖에 서 있다는 보고가 들어왔다. 안에는 말씀을 듣는 무리가, 밖에는 혈연 가족이 서 있다. 이 장면이 영적 진리를 보여준다", "예화_적용":"교회 건물 안에 있는 것과 말씀 안에 있는 것은 다르다"},{"대지":"1대지: 밖에 선 가족 (육적 관계의 위치)", "내용":"예수님의 가족이 밖에 서 있다. 가장 가까운 관계이지만 말씀의 자리 밖에 있었다", "예화_적용":"가족이라는 이유만으로 자동으로 구원받는 것은 아니다"},{"대지":"2대지: 안에 앉은 무리 (영적 관계의 위치)", "내용":"말씀을 듣기 위해 안에 모인 무리가 육적 가족보다 예수님께 더 가까이 있었다", "예화_적용":"예배 시간에 말씀 앞에 앉아있는 것이 가장 복된 자리이다"},{"대지":"3대지: 보려고 기다림 (만남의 갈망)", "내용":"밖에 서서 기다리는 것은 만남을 갈망하는 것이다. 예수님은 이 만남을 영적으로 재정의하신다", "예화_적용":"예수님을 만나고 싶다면 말씀 안으로 들어오라"},{"대지":"결론", "내용":"지금 나는 밖에 서 있는가 안에 앉아있는가. 말씀을 듣는 자리 안으로 들어오라. 그곳이 예수님과 가장 가까운 자리이다", "예화_적용":"오늘 예배에 온 것은 안으로 들어온 것이다. 마음도 말씀 안으로 들여놓으라"}],
표7_찬송가: [{"새찬송가":"364", "통일찬송가":"400", "제목":"내 주를 가까이 하게 함은", "선정이유":"주님께 가까이 나아감"},{"새찬송가":"312", "통일찬송가":"283", "제목":"주 하나님 앞에", "선정이유":"하나님의 임재 안으로 나아옴"},{"새찬송가":"279", "통일찬송가":"253", "제목":"주님의 뜻을 이루소서", "선정이유":"주님의 뜻 안에 거하고자 하는 소망"},{"새찬송가":"316", "통일찬송가":"266", "제목":"주의 사랑 안에 거하라", "선정이유":"주님 안에 거하는 영적 친밀함"}],
표8_상담적용: [{"상황":"예배에는 오지만 마음이 밖에 있는 분", "성경원리":"몸은 안에 있지만 마음은 밖에 있을 수 있다", "실제적용":"예배 전 모든 걱정과 생각을 하나님께 맡기는 기도를 하라"},{"상황":"가족을 교회에 데려오고 싶은 분", "성경원리":"밖에 있는 가족도 결국 안으로 들어올 수 있다", "실제적용":"강요하지 말고 기도하라. 삶으로 보여주면 자연스럽게 궁금해할 것이다"},{"상황":"하나님이 멀게 느껴지는 분", "성경원리":"예수님은 문 앞에 서서 두드리신다(계 3:20). 문을 여는 것은 우리의 몫이다", "실제적용":"매일 정해진 시간에 기도하고 말씀을 읽으라. 꾸준함이 친밀함을 만든다"}],
표9_교차참조: [{"구절":"출 34:29-35", "연결점":"모세가 하나님의 임재에서 나올 때 백성은 밖에 있었다", "구분":"구약"},{"구절":"왕상 8:10-11", "연결점":"여호와의 영광이 성전에 가득하여 제사장이 들어가지 못함", "구분":"구약"},{"구절":"시 84:10", "연결점":"하나님의 궁정에 하루 있는 것이 다른 곳에서 천 날보다 나은즉", "구분":"구약"},{"구절":"사 55:6", "연결점":"너희는 여호와를 만날 만한 때에 찾으라", "구분":"구약"},{"구절":"계 3:20", "연결점":"내가 문 밖에 서서 두드리노니 누구든지 열면", "구분":"신약"},{"구절":"히 10:19-22", "연결점":"예수의 피를 힘입어 성소에 들어갈 담력을 얻었나니", "구분":"신약"},{"구절":"엡 2:13", "연결점":"전에는 멀리 있던 너희가 그리스도 예수 안에서 가까워졌느니라", "구분":"신약"},{"구절":"요 10:9", "연결점":"내가 문이니 누구든지 나로 말미암아 들어가면 구원을 얻고", "구분":"신약"}]
};

pastorCommentaryData["누가복음_8_21"] = {
본문: "예수께서 대답하여 가라사대 내 모친과 내 동생들은 곧 하나님의 말씀을 듣고 행하는 이 사람들이라 하시니라",
표1_원어분석: [{"원어":"ἀποκριθείς (아포크리데이스)", "의미_문법":"대답하여 - 분사 과거 수동태. 응답하다", "설교포인트":"예수님의 대답은 영적 가족의 정의를 바꾸는 선언이다"},{"원어":"μήτηρ μου καὶ ἀδελφοί μου (메테르 무 카이 아델포이 무)", "의미_문법":"내 모친과 내 동생들 - 명사구. 혈연 가족을 재정의하심", "설교포인트":"예수님은 가족의 개념을 영적으로 재정의하셨다"},{"원어":"ἀκούοντες (아쿠온테스)", "의미_문법":"듣는 - 분사 현재. 계속 듣는 자", "설교포인트":"말씀을 듣는 것이 하나님 가족의 첫째 조건이다"},{"원어":"ποιοῦντες (포이운테스)", "의미_문법":"행하는 - 분사 현재. 계속 행하는 자", "설교포인트":"듣기만이 아니라 행하는 것이 가족의 증거이다"},{"원어":"τὸν λόγον τοῦ θεοῦ (톤 로곤 투 데우)", "의미_문법":"하나님의 말씀을 - 명사구 목적격. 하나님의 말씀", "설교포인트":"하나님 가족의 기준은 하나님의 말씀이다"}],
표2_역사적배경: [{"항목":"가족 중심 사회에서의 충격", "내용":"1세기 유대 사회는 혈연 중심의 사회였다. 가족 관계는 가장 중요한 사회적 유대였다. 예수님의 이 말씀은 혁명적이었다", "목회적활용":"예수님은 사회의 가장 근본적 관계를 재정의하셨다"},{"항목":"새로운 공동체의 선언", "내용":"예수님은 혈연이 아닌 말씀을 듣고 행하는 것을 기준으로 새로운 가족 공동체를 형성하셨다. 이것이 교회의 원형이다", "목회적활용":"교회는 혈연이 아닌 말씀으로 연결된 영적 가족이다"},{"항목":"제자들에 대한 격려", "내용":"혈연 가족을 떠나 예수님을 따른 제자들에게 이 말씀은 큰 위로와 격려였다", "목회적활용":"주를 위해 가족을 떠난 자에게 영적 가족이라는 더 큰 가족이 주어진다"}],
표3_신학적의미: [{"교리":"영적 가족의 정의", "설명":"하나님의 가족은 혈연이 아니라 말씀을 듣고 행하는 것으로 결정된다. 이것이 교회 공동체의 신학적 기초이다", "관련구절":"요 1:12-13"},{"교리":"말씀 순종의 우선성", "설명":"듣고 행하는 것이 가족 관계의 기준이다. 순종이 신앙의 핵심 표현이다", "관련구절":"요 14:15"},{"교리":"그리스도 안의 새 가족", "설명":"그리스도를 통해 하나님의 자녀가 되는 새로운 가족 관계가 형성된다", "관련구절":"엡 2:19"}],
표4_예표론: [{"구분":"구약 예표", "내용":"룻이 혈연이 아닌 신앙으로 이스라엘 가족에 편입된 것(룻 1:16)", "그리스도연결":"신앙이 혈연을 넘어 하나님의 가족으로 만든다"},{"구분":"성취", "내용":"예수님이 말씀을 듣고 행하는 자를 가족이라 선언하심", "그리스도연결":"그리스도는 새로운 영적 가족의 머리이시다"},{"구분":"완성", "내용":"모든 민족에서 나온 하나님의 가족이 함께 모임(계 7:9)", "그리스도연결":"혈통, 민족을 넘어 하나님의 가족이 완성된다"}],
표5_매튜헨리: [{"영어원문":"Christ's kindred are those who hear the word of God and do it; these are nearer and dearer to him than any relation of flesh and blood", "한국어번역":"그리스도의 친족은 하나님의 말씀을 듣고 행하는 자들이다. 이들은 어떤 혈연관계보다 더 가깝고 소중하다", "핵심통찰":"말씀 순종이 혈연보다 더 깊은 관계를 만든다"},{"영어원문":"It is a great honour to be related to Christ by faith and obedience, greater than to be related to him by flesh", "한국어번역":"믿음과 순종으로 그리스도와 관계를 맺는 것은 큰 영광이며, 육으로 관계를 맺는 것보다 더 크다", "핵심통찰":"영적 관계가 육적 관계보다 더 큰 영광이다"}],
표6_설교자료: [{"대지":"제목", "내용":"듣고 행하는 자 — 예수님의 참 가족", "예화_적용":"하나님의 말씀을 듣고 행하는 것이 예수님의 가족이 되는 길이다"},{"대지":"서론", "내용":"예수님의 대답은 충격적이다. 어머니와 형제를 제쳐놓고 말씀을 듣고 행하는 사람들을 가족이라 하신다. 이것은 가족을 무시하는 것이 아니라 영적 가족의 개념을 선언하시는 것이다", "예화_적용":"교회는 피가 아니라 말씀으로 연결된 가족이다"},{"대지":"1대지: 듣고 (말씀을 듣는 자)", "내용":"하나님의 말씀을 듣는 것이 영적 가족의 첫째 조건이다. 듣는다는 것은 귀를 기울이고 관심을 가지는 것이다", "예화_적용":"매주 예배에 와서 말씀을 듣는 것이 가족의 시작이다"},{"대지":"2대지: 행하는 (말씀을 실천하는 자)", "내용":"듣기만이 아니라 행하는 것이 필요하다. 순종이 사랑의 표현이며 가족의 증거이다", "예화_적용":"이번 주 들은 말씀 중 하나를 실천하는 것이 가족의 증거이다"},{"대지":"3대지: 이 사람들이라 (새로운 가족 선언)", "내용":"예수님은 지금 여기서 말씀을 듣고 있는 사람들을 가리키며 '이 사람들'이라 하셨다. 이것이 교회의 원형이다", "예화_적용":"지금 이 자리에서 말씀을 듣고 있는 우리가 예수님의 가족이다"},{"대지":"결론", "내용":"예수님의 가족이 되는 것은 혈연이 아니라 말씀을 듣고 행하는 것이다. 이 자리에서 예수님의 가족이 되는 결단을 하자", "예화_적용":"오늘 말씀을 듣고 순종하겠다는 결단이 가족 입양 서류이다"}],
표7_찬송가: [{"새찬송가":"291", "통일찬송가":"259", "제목":"주의 말씀 듣고서", "선정이유":"말씀을 듣고 행하는 삶"},{"새찬송가":"497", "통일찬송가":"380", "제목":"내 주 하나님 넓고 큰 은혜는", "선정이유":"하나님의 자녀가 되는 은혜"},{"새찬송가":"347", "통일찬송가":"309", "제목":"주 예수 넓은 품에", "선정이유":"그리스도의 가족 안에 들어감"},{"새찬송가":"534", "통일찬송가":"490", "제목":"주의 참된 제자 되어", "선정이유":"말씀을 듣고 행하는 제자의 삶"}],
표8_상담적용: [{"상황":"교회 공동체에 소속감을 느끼지 못하는 분", "성경원리":"교회는 혈연이 아닌 말씀으로 연결된 영적 가족이다", "실제적용":"소그룹에 참여하여 함께 말씀을 나누라. 영적 가족의 친밀함을 경험하게 될 것이다"},{"상황":"신앙의 가족과 혈연 가족 사이에서 갈등하는 분", "성경원리":"예수님은 두 관계를 모두 중요하게 여기셨다. 다만 영적 관계가 우선이다", "실제적용":"가족을 사랑하되 하나님의 뜻을 먼저 순종하라"},{"상황":"말씀을 듣지만 실천이 어려운 분", "성경원리":"듣고 행하는 것이 예수님의 가족이 되는 조건이다", "실제적용":"큰 것부터 시작하지 말고 작은 순종부터 시작하라. 작은 순종이 큰 순종의 씨앗이다"}],
표9_교차참조: [{"구절":"룻 1:16", "연결점":"어머니의 백성이 나의 백성이 되고 어머니의 하나님이 나의 하나님이 되시리니", "구분":"구약"},{"구절":"시 119:63", "연결점":"나는 주를 경외하는 자와 주의 법도를 지키는 자의 동무이니이다", "구분":"구약"},{"구절":"삼상 18:1", "연결점":"요나단의 마음이 다윗의 마음에 연결되어 — 영적 유대", "구분":"구약"},{"구절":"사 66:2", "연결점":"마음이 겸손하고 통회하며 내 말을 두려워하는 자", "구분":"구약"},{"구절":"요 1:12-13", "연결점":"그를 영접하는 자 곧 그 이름을 믿는 자들에게는 하나님의 자녀가 되는 권세를 주셨으니", "구분":"신약"},{"구절":"요 14:15", "연결점":"너희가 나를 사랑하면 나의 계명을 지키리라", "구분":"신약"},{"구절":"엡 2:19", "연결점":"너희는 더 이상 외인이나 나그네가 아니요 성도들과 동일한 시민이요 하나님의 권속이라", "구분":"신약"},{"구절":"약 1:22", "연결점":"너희는 말씀을 행하는 자가 되고 듣기만 하여 자신을 속이는 자가 되지 말라", "구분":"신약"}]
};
