pastorCommentaryData["누가복음_9_62"] = {
본문: "예수께서 이르시되 손에 쟁기를 잡고 뒤를 돌아보는 자는 하나님의 나라에 합당치 아니하니라 하시니라",
표1_원어분석: [{"원어":"ἄροτρον (아로트론)", "의미_문법":"쟁기 - 명사 대격. 농기구", "설교포인트":"쟁기는 사명/사역의 상징"},{"원어":"ἐπιβαλὼν (에피발론)", "의미_문법":"잡다/올려놓다 - 분사 과거. 손을 대어", "설교포인트":"사역을 시작한 사람"},{"원어":"βλέπων (블레폰)", "의미_문법":"보다/돌아보다 - 분사 현재. 바라보는", "설교포인트":"현재 분사 — 계속 뒤를 돌아봄"},{"원어":"ὀπίσω (오피소)", "의미_문법":"뒤로 - 부사. 뒤쪽으로", "설교포인트":"뒤를 돌아보는 것은 미련과 후퇴"},{"원어":"εὔθετός (유데토스)", "의미_문법":"합당한/적합한 - 형용사 주격. 알맞은", "설교포인트":"하나님 나라에 부적합하다는 선언"}],
표2_역사적배경: [{"항목":"쟁기질의 비유", "내용":"고대 팔레스타인의 쟁기는 한 손으로 잡고 한 손으로 소를 모는 구조였다. 앞을 보지 않으면 곧은 이랑을 만들 수 없었다", "목회적활용":"사명에 집중하지 않으면 올바른 결과를 낼 수 없다"},{"항목":"뒤를 돌아봄", "내용":"쟁기질하면서 뒤를 돌아보면 이랑이 구부러진다. 사명에 집중하지 못하는 상태이다", "목회적활용":"과거에 미련을 두면 현재 사명에 충실할 수 없다"},{"항목":"합당치 않음", "내용":"'합당치 않다'는 매우 강한 표현이다. 하나님 나라에 적합하지 않다는 것이다", "목회적활용":"중도 포기와 미련은 하나님 나라 사역에 치명적이다"}],
표3_신학적의미: [{"교리":"전진하는 제자도", "설명":"제자도는 앞으로 나아가는 것이다. 뒤를 돌아보는 것은 제자도의 본질에 어긋난다", "관련구절":"빌 3:13-14"},{"교리":"집중된 헌신", "설명":"쟁기질은 집중력을 요구한다. 하나님 나라 사역도 온전한 집중을 요구한다", "관련구절":"고전 7:35"},{"교리":"롯의 아내의 교훈", "설명":"뒤를 돌아본 롯의 아내가 소금 기둥이 된 것처럼, 과거에 미련을 두면 파멸한다", "관련구절":"창 19:26"}],
표4_예표론: [{"구분":"구약 예표", "내용":"롯의 아내가 뒤를 돌아보아 소금 기둥이 됨(창 19:26)", "그리스도연결":"뒤를 돌아보는 것의 치명적 결과"},{"구분":"성취", "내용":"예수님이 뒤를 돌아보지 말라고 명령하심", "그리스도연결":"전진하는 제자도를 요구하심"},{"구분":"완성", "내용":"달려갈 길을 인내로 달리는 자들(히 12:1)", "그리스도연결":"끝까지 전진하여 완주하는 성도"}],
표5_매튜헨리: [{"영어원문":"No man having put his hand to the plough, and looking back, is fit for the kingdom of God — the ploughman who looks behind him makes crooked furrows", "한국어번역":"손에 쟁기를 잡고 뒤를 돌아보는 자는 하나님의 나라에 합당치 아니하니라 — 뒤를 돌아보는 농부는 구부러진 이랑을 만든다", "핵심통찰":"뒤를 돌아보면 곧은 길을 갈 수 없다"},{"영어원문":"Looking back is an evidence that the heart is not right with God — those who have begun well must persevere, or they will lose all", "한국어번역":"뒤를 돌아보는 것은 마음이 하나님과 바르지 않다는 증거이다 — 잘 시작한 자도 끝까지 견디어야 한다. 그렇지 않으면 모든 것을 잃는다", "핵심통찰":"시작만이 아니라 끝까지 견디는 것이 중요하다"}],
표6_설교자료: [{"대지":"제목", "내용":"뒤를 돌아보지 말라", "예화_적용":"앞을 향해 전진하는 것이 제자도이다"},{"대지":"서론", "내용":"쟁기를 잡았으면 앞만 보아야 한다. 뒤를 돌아보면 이랑이 구부러진다. 예수님이 마지막으로 하신 말씀이 이것이다 — 뒤를 돌아보는 자는 하나님 나라에 합당치 않다", "예화_적용":"운전하면서 뒤만 보면 사고가 난다"},{"대지":"1대지: 손에 쟁기를 잡고 (사역의 시작)", "내용":"쟁기를 잡은 것은 사역을 시작한 것이다. 시작은 좋았다", "예화_적용":"시작이 반이라지만 나머지 반이 더 중요하다"},{"대지":"2대지: 뒤를 돌아보는 자 (미련과 후퇴)", "내용":"뒤를 돌아보는 것은 과거에 대한 미련, 떠나온 것에 대한 후회, 편안했던 시절에 대한 그리움이다", "예화_적용":"출애굽한 이스라엘이 애굽의 고기를 그리워한 것처럼"},{"대지":"3대지: 합당치 아니하니라 (엄중한 경고)", "내용":"이것은 매우 강한 경고이다. 뒤를 돌아보면 하나님 나라 사역에 부적합하다", "예화_적용":"반쪽짜리 헌신은 헌신이 아니다"},{"대지":"결론", "내용":"쟁기를 잡았으면 앞만 보고 가라. 과거에 미련을 두지 말라. 하나님 나라가 앞에 있다", "예화_적용":"오늘 뒤를 돌아보는 것을 그만두고 앞만 보라"}],
표7_찬송가: [{"새찬송가":"384", "통일찬송가":"291", "제목":"내 주의 뜻대로 행하게 하소서", "선정이유":"앞을 향해 나아감"},{"새찬송가":"176", "통일찬송가":"174", "제목":"저 높은 곳을 향하여", "선정이유":"높은 곳을 향한 전진"},{"새찬송가":"488", "통일찬송가":"348", "제목":"십자가를 질 수 있나", "선정이유":"끝까지 가는 결단"},{"새찬송가":"435", "통일찬송가":"322", "제목":"부름 받아 나선 이 몸", "선정이유":"사명을 향한 전진"}],
표8_상담적용: [{"상황":"과거에 미련이 있는 분", "성경원리":"뒤를 돌아보면 하나님 나라에 합당치 않다. 과거를 놓아야 한다", "실제적용":"과거를 정리하고 앞을 향해 나아가라. 뒤를 돌아보는 것을 멈추라"},{"상황":"사역을 중도 포기하려는 분", "성경원리":"쟁기를 잡았으면 끝까지 가야 한다. 중도 포기는 합당치 않다", "실제적용":"힘들어도 포기하지 말라. 끝까지 견디는 자에게 상급이 있다"},{"상황":"새 시작이 두려운 분", "성경원리":"앞만 보고 나아가라. 뒤를 돌아보면 전진할 수 없다", "실제적용":"두려움을 인정하되 두려움에 사로잡히지 말라. 앞에 계신 주님을 바라보라"}],
표9_교차참조: [{"구절":"창 19:26", "연결점":"롯의 아내가 뒤를 돌아보매 소금 기둥이 되었더라", "구분":"구약"},{"구절":"사 43:18-19", "연결점":"이전 것을 기억하지 말라 보라 내가 새 일을 행하리니", "구분":"구약"},{"구절":"잠 4:25-27", "연결점":"네 눈은 바로 보며 네 눈꺼풀은 네 앞을 곧게 살펴라", "구분":"구약"},{"구절":"민 11:5", "연결점":"우리가 애굽에서 값없이 먹던 생선이 생각나는도다 — 과거에 대한 미련", "구분":"구약"},{"구절":"빌 3:13-14", "연결점":"뒤에 있는 것은 잊어버리고 앞에 있는 것을 잡으려고", "구분":"신약"},{"구절":"히 12:1-2", "연결점":"인내로서 우리 앞에 당한 경주를 하며 예수를 바라보자", "구분":"신약"},{"구절":"눅 17:32", "연결점":"롯의 처를 생각하라 — 예수님 자신이 뒤돌아봄의 위험을 경고", "구분":"신약"},{"구절":"갈 5:7", "연결점":"너희가 달음질을 잘 하더니 누가 너희를 막아 진리를 순종치 못하게 하더냐", "구분":"신약"}]
};
